('51a7795a-ffae-5fbe-b063-505452de6d92','fd88be6c-0e80-5b7c-99cd-63370adf2ec2',1,'adjective','A1','S2','W2',null,'[{"phrase":"the present day","register":null,"definition_en":"in the time now, or modern times","translation":"در زمان حال، یا دوران مدرن","example":"The practice has continued from medieval times to the present day.","example_translation":"این عمل از قرون وسطی تا به امروز ادامه داشته است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560849.mp3"},{"phrase":"all present and correct","register":null,"definition_en":"used to say that everyone who is supposed to be in a place, at a meeting etc is now here","translation":"می گفت هرکسی که قرار است در یک مکان، در یک جلسه و غیره باشد، اکنون اینجاست","example":"","example_translation":"","example_audio_url":""},{"phrase":"present company excepted","register":"spoken","definition_en":"used when you are criticizing a group of people and you want to tell the people you are with that they are not included in the criticism","translation":"زمانی استفاده می شود که از گروهی از افراد انتقاد می کنید و می خواهید به افرادی که با آنها هستید بگویید که آنها شامل انتقاد نمی شوند.","example":"Women are never satisfied with anything! Present company excepted, of course.","example_translation":"زن ها هرگز از چیزی راضی نیستند! البته شرکت فعلی به استثنای","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000324373.mp3"}]'::jsonb),
('e814b5d3-4e03-54c7-88e3-03c413afcce2','fd88be6c-0e80-5b7c-99cd-63370adf2ec2',2,'verb','A1','S2','W1',null,'[{"phrase":"present yourself","register":null,"definition_en":"to talk and behave in a particular way when you meet people","translation":"صحبت کردن و رفتار خاصی در هنگام ملاقات با مردم","example":"He presents himself well.","example_translation":"خودش را خوب معرفی می کند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560872.mp3"},{"phrase":"something presents itself","register":null,"definition_en":"if a situation, opportunity etc presents itself, it suddenly happens or exists","translation":"اگر موقعیت، فرصت و غیره خود را نشان دهد، ناگهان اتفاق می افتد یا وجود دارد","example":"I’ll tell her as soon as the opportunity presents itself .","example_translation":"به محض اینکه فرصت پیش بیاید به او می گویم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000324441.mp3"},{"phrase":"present arms","register":null,"definition_en":"when soldiers present arms , they hold their guns straight up in front of them while an officer or other important person walks past","translation":"وقتی سربازان اسلحه‌های خود را ارائه می‌کنند، اسلحه‌های خود را مستقیماً در مقابل خود نگه می‌دارند در حالی که یک افسر یا شخص مهم دیگری از کنار آنها عبور می‌کند.","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
('a1293f99-ea76-5c1d-9484-365e5b18971d','fd88be6c-0e80-5b7c-99cd-63370adf2ec2',3,'noun','A1','S2','W3',null,'[{"phrase":"the present","register":"technical","definition_en":"the time that is happening now","translation":"زمانی که اکنون در حال وقوع است","example":"Stop worrying about the past and live in the present.","example_translation":"نگران گذشته نباشید و در زمان حال زندگی کنید.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560911.mp3"},{"phrase":"at present","register":null,"definition_en":"at this time","translation":"در این زمان","example":"The item you want is not available at present.","example_translation":"مورد مورد نظر شما در حال حاضر موجود نیست.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560925.mp3"},{"phrase":"for the present","register":null,"definition_en":"something that exists or will be done for the present exists now and will continue for a while, though it may change in the future","translation":"چیزی که در حال حاضر وجود دارد یا انجام خواهد شد، اکنون وجود دارد و برای مدتی ادامه خواهد داشت، هرچند ممکن است در آینده تغییر کند.","example":"The company is still in business, at least for the present.","example_translation":"این شرکت حداقل در حال حاضر هنوز در تجارت است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560929.mp3"}]'::jsonb),
