('14358e18-e96d-59c8-936c-5b951fc234b0','1d0febd1-2174-5781-9283-f2d75d194eee',1,'noun','A2','S2','W1','( plural varieties )','[{"phrase":"a variety of something","register":null,"definition_en":"a lot of things of the same type that are different from each other in some way","translation":"بسیاری از چیزها از یک نوع که به نوعی با یکدیگر متفاوت هستند","example":"The girls come from a variety of different backgrounds.","example_translation":"دختران از پیشینه‌های مختلف هستند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001548227.mp3"},{"phrase":"variety is the spice of life","register":null,"definition_en":"used to say that doing a lot of different things, meeting different people etc is what makes life interesting","translation":"می‌گفتند انجام کارهای مختلف، ملاقات با افراد مختلف و غیره چیزی است که زندگی را جذاب می‌کند","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
