('f60f97b6-51ed-5729-bf34-112bd7e0232d','78928235-022a-5ac5-8569-2a1e56ffbcab',1,'noun','A1','S1','W2',null,'[{"phrase":"the weather","register":"informal","definition_en":"a description on radio or television , in newspapers etc of what the weather will be like in the near future","translation":"توضیحی در رادیو یا تلویزیون، در روزنامه ها و غیره از وضعیت آب و هوا در آینده نزدیک","example":"I always watch the weather after the news.","example_translation":"من همیشه بعد از اخبار هوا را تماشا می کنم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000512786.mp3"},{"phrase":"under the weather","register":"informal","definition_en":"slightly ill","translation":"کمی بیمار","example":"You look a bit under the weather.","example_translation":"شما کمی زیر آب و هوا به نظر می رسید.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000512798.mp3"}]'::jsonb),
