('5fe14c27-d9d2-5fa8-8db7-22c07878e5b3','b46aa84b-01db-58b3-b3dc-1af2548e1bcd',1,null,null,'spoken & written','not having any mistakes , faults , or damage',null,null,'کامل، بی‌نقص؛ کامل (مطابقت)؛ ایده‌آل (حالت)','{}'::text[],'{}'::text[],array['absolutely perfect His sight is absolutely perfect.','quite perfect written (= absolutely perfect ) The old bottle was very dark blue and quite perfect.','almost/nearly/near perfect His collection included an almost perfect skeleton of an armadillo. Her performance was near perfect.','less than perfect (= not perfect ) So many excellent writers, for example Byron and Keats, were less than perfect spellers.','far from perfect (= not at all perfect ) The weather conditions were far from perfect.','technically perfect The system was technically perfect.']::text[],'[{"sentence":"His English was perfect.","translation":"انگلیسیش عالی بود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559853.mp3"},{"sentence":"The car was in perfect condition.","translation":"ماشین کاملا سالم بود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349958.mp3"},{"sentence":"You’re very lucky to have perfect teeth.","translation":"شما بسیار خوش شانس هستید که دندان های عالی دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349957.mp3"},{"sentence":"a perfect performance","translation":"یک اجرای کامل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349956.mp3"},{"sentence":"In a perfect world , we wouldn’t need an army.","translation":"در یک دنیای عالی، ما به ارتش نیاز نداریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001765606.mp3"}]'::jsonb,5),
('1019ec09-25c5-5539-a1ef-fc0671d027e2','b46aa84b-01db-58b3-b3dc-1af2548e1bcd',2,null,null,'spoken & written','as good as possible, or the best of its kind',null,null,'تا حد امکان خوب یا بهترین در نوع خود','{}'::text[],'{}'::text[],array['absolutely perfect His sight is absolutely perfect.','quite perfect written (= absolutely perfect ) The old bottle was very dark blue and quite perfect.','almost/nearly/near perfect His collection included an almost perfect skeleton of an armadillo. Her performance was near perfect.','less than perfect (= not perfect ) So many excellent writers, for example Byron and Keats, were less than perfect spellers.','far from perfect (= not at all perfect ) The weather conditions were far from perfect.','technically perfect The system was technically perfect.']::text[],'[{"sentence":"The weather was perfect the whole week.","translation":"هوا در کل هفته عالی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349946.mp3"},{"sentence":"a perfect example of Gothic architecture","translation":"نمونه ای کامل از معماری گوتیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349947.mp3"},{"sentence":"The clothes were a perfect fit.","translation":"لباس ها کاملاً مناسب بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001765609.mp3"},{"sentence":"a perfect solution to the problem","translation":"یک راه حل کامل برای مشکل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559866.mp3"},{"sentence":"Ronnie was in perfect health.","translation":"رونی در سلامت کامل بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001765610.mp3"},{"sentence":"Good, you’re home. Perfect timing – dinner’s on the table.","translation":"خوب تو خونه هستی زمان مناسب - شام روی میز است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001839817.mp3"}]'::jsonb,6),
('9b82caab-f9fa-5ac3-91f8-da1e4fb2c2b1','b46aa84b-01db-58b3-b3dc-1af2548e1bcd',3,null,null,'spoken & written','exactly what is needed for a particular purpose , situation, or person',null,null,'دقیقاً آنچه برای یک هدف، موقعیت یا شخص خاص مورد نیاز است',array['ideal']::text[],'{}'::text[],array['absolutely perfect His sight is absolutely perfect.','quite perfect written (= absolutely perfect ) The old bottle was very dark blue and quite perfect.','almost/nearly/near perfect His collection included an almost perfect skeleton of an armadillo. Her performance was near perfect.','less than perfect (= not perfect ) So many excellent writers, for example Byron and Keats, were less than perfect spellers.','far from perfect (= not at all perfect ) The weather conditions were far from perfect.','technically perfect The system was technically perfect.']::text[],'[{"sentence":"That’s perfect! Just the way I wanted it to look.","translation":"این کامل است! همان طور که می خواستم به نظر برسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349972.mp3"},{"sentence":"Crusty bread is the perfect accompaniment to this soup.","translation":"نان کراستی همراهی عالی برای این سوپ است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559875.mp3"},{"sentence":"The land is perfect for sheep farming.","translation":"زمین برای پرورش گوسفند مناسب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559878.mp3"},{"sentence":"She thought she’d found the perfect place to live.","translation":"او فکر می کرد که مکان مناسبی برای زندگی پیدا کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559882.mp3"},{"sentence":"a perfect day for a picnic","translation":"یک روز عالی برای پیک نیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559885.mp3"},{"sentence":"the perfect actor for the part","translation":"بازیگر عالی برای نقش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000349976.mp3"}]'::jsonb,6),
