('10f3b40d-a1be-507a-bdcc-e83e342f3c24','7ec9b155-947e-5b16-a6e3-b3fdc35bd6ef',1,null,null,'spoken & written','used to say that something may be true, but you are not sure',null,null,'شاید، گمان می‌کنم؛ شاید (احتمال)',array['maybe']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Perhaps she’s next door.","translation":"شاید اون همسایه باشه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351079.mp3"},{"sentence":"Perhaps it will snow tomorrow.","translation":"شاید فردا برف بیاد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559984.mp3"},{"sentence":"It won’t take so long next time, perhaps.","translation":"شاید دفعه بعد خیلی طول نکشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559985.mp3"},{"sentence":"‘I don’t think you understand.’ ‘Well, perhaps not .’","translation":"«فکر نمی‌کنم بفهمی.» «خب، شاید نه.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559986.mp3"},{"sentence":"It might snow tomorrow.","translation":"ممکنه فردا برف بیاد","audio_url":null}]'::jsonb,5),
('b93d6085-e6bb-5e14-a112-0cefe4bfcb00','7ec9b155-947e-5b16-a6e3-b3fdc35bd6ef',2,null,null,'spoken & written','used to give your opinion, when you do not want to be too definite',null,null,'زمانی که نمی خواهید خیلی قطعی باشید، برای بیان نظر خود استفاده می شود',array['maybe']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This is perhaps her finest novel yet.","translation":"شاید این بهترین رمان او باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351078.mp3"},{"sentence":"The industrial revolution was, perhaps, the most important event in history.","translation":"انقلاب صنعتی شاید مهمترین رویداد تاریخ بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559993.mp3"}]'::jsonb,2),
('9872d954-08e1-574d-9465-0e6b66962a90','7ec9b155-947e-5b16-a6e3-b3fdc35bd6ef',3,null,null,'spoken & written','used to say that a number is only a guess',null,null,'قبلاً می گفتند که یک عدد فقط یک حدس است',array['maybe']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The room was large, perhaps 20 feet square.","translation":"اتاق بزرگ بود، شاید 20 فوت مربع.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020167.mp3"},{"sentence":"Perhaps 200 people were there.","translation":"شاید 200 نفر آنجا بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559995.mp3"}]'::jsonb,2),
('acf62dc6-7764-5deb-b2e9-152abd752146','7ec9b155-947e-5b16-a6e3-b3fdc35bd6ef',4,null,null,'spoken','used to politely ask or suggest something, or say what you are going to do',null,null,'معمولاً مودبانه چیزی را می پرسید یا پیشنهاد می کرد یا می گفت که قرار است چه کاری انجام دهید',array['maybe']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I thought perhaps we’d have lunch in the garden.","translation":"فکر کردم شاید ناهار را در باغ بخوریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351092.mp3"}]'::jsonb,1),
('a0b6c52b-6047-5445-b5b2-92629d25cfb8','8933e1f3-8d37-5ac0-ad82-ce6a5693a39e',1,null,null,'spoken & written','the science concerned with the study of physical objects and substances , and of natural forces such as light, heat , and movement',null,null,'فیزیک (علم)، طبیعت‌شناسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"To me, physics is a fascinating subject.","translation":"برای من، فیزیک یک موضوع جذاب است.","audio_url":null}]'::jsonb,1),
('9de765eb-dcc3-57fc-bba3-8bc775ab0fd4','7594c466-c6b7-58e5-8f06-61cca3e760df',1,'painting/drawing','نقاشی/طراحی','spoken & written','shapes, lines etc painted or drawn on a surface, showing what someone or something looks like','[ countable ]',null,'تصویر، عکس؛ تابلو (نقاشی)؛ تصویر (ذهنی)','{}'::text[],'{}'::text[],array['draw/paint a picture She drew a picture of a mushroom on the blackboard.','do a picture of somebody/something (= draw or paint a picture ) He’s done a picture of a monster.','a picture hangs somewhere Three pictures hung on the wall over his bed.','a picture shows something formal The picture shows two women leaning down towards a third.','a picture is of somebody/something (= used to talk about what a picture shows ) There''s a picture of his wife above the fireplace.']::text[],'[{"sentence":"The room had several pictures on the walls.","translation":"چند عکس روی دیوار اتاق نصب شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537916.mp3"},{"sentence":"a book with pictures in it","translation":"یک کتاب با تصاویر در آن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537917.mp3"},{"sentence":"I like that picture of the two horses.","translation":"من آن عکس دو اسب را دوست دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000360602.mp3"},{"sentence":"Draw a picture of your house.","translation":"یک تصویر از خانه خود بکشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537922.mp3"},{"sentence":"He asked her permission to paint her picture (= paint a picture of her ) .","translation":"از او اجازه خواست تا تصویر او را نقاشی کند (= تصویری از او بکشد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537923.mp3"}]'::jsonb,5),
('acf1ddbf-6662-5385-9777-4a946137f7a6','7594c466-c6b7-58e5-8f06-61cca3e760df',2,'photograph','عکس','spoken & written','a photograph','[ countable ]',null,'یک عکس','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"That’s a great picture of you, Dad!","translation":"این یک عکس عالی از شما است، پدر!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537934.mp3"},{"sentence":"I asked the waiter if he’d mind taking our picture.","translation":"از گارسون پرسیدم که آیا او بدش می آید که از ما عکس بگیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537937.mp3"},{"sentence":"Would you like to see the wedding pictures?","translation":"آیا دوست دارید عکس های عروسی را ببینید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537940.mp3"}]'::jsonb,3),
('bc41a148-73ff-5721-93c7-3478babda3c8','7594c466-c6b7-58e5-8f06-61cca3e760df',3,'television','تلویزیون','spoken & written','an image that appears on a television or cinema screen','[ countable ]',null,'تصویری که روی صفحه تلویزیون یا سینما ظاهر می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"upsetting pictures of the famine in Africa","translation":"تصاویر ناراحت کننده از قحطی در آفریقا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537941.mp3"},{"sentence":"satellite pictures from space","translation":"تصاویر ماهواره ای از فضا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537942.mp3"}]'::jsonb,2),
('efb91558-5dd2-5d69-8957-5f9d7e75ab09','7594c466-c6b7-58e5-8f06-61cca3e760df',4,'description/idea','توضیحات/ایده','spoken & written','a description or idea of what something is like','[ countable usually singular ]',null,'توصیف یا ایده ای از اینکه چیزی شبیه است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The book gives you a good picture of what life was like in Japan in the early 19th century.","translation":"این کتاب تصویر خوبی از زندگی در ژاپن در اوایل قرن نوزدهم به شما می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001202.mp3"},{"sentence":"The article paints a rather bleak picture of the future of our planet.","translation":"این مقاله تصویری نسبتاً تاریک از آینده سیاره ما ترسیم می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001203.mp3"},{"sentence":"Detectives are trying to build up a picture of the kidnapper.","translation":"کارآگاهان در حال تلاش برای ساختن تصویری از آدم ربا هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537957.mp3"},{"sentence":"The description in the guidebook showed rather a rosy picture (= one that makes you think that something is better than it really is ) .","translation":"توضیحات کتاب راهنما یک تصویر گلگون را نشان می دهد (= تصویری که باعث می شود فکر کنید چیزی بهتر از چیزی است که واقعاً هست).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001204.mp3"},{"sentence":"I now have a vivid picture (= very clear picture ) in my mind.","translation":"من اکنون یک تصویر واضح (= تصویر بسیار واضح) در ذهنم دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001205.mp3"}]'::jsonb,5),
('fa109ed0-e0e7-546a-aeef-bac23740ff0c','7594c466-c6b7-58e5-8f06-61cca3e760df',5,'situation','وضعیت','spoken & written','the general situation in a place, organization etc','[ singular ]',null,'وضعیت کلی در یک مکان، سازمان و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The worldwide picture for tribal people remains grim.","translation":"تصویر جهانی برای افراد قبیله ای همچنان تلخ است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000360610.mp3"},{"sentence":"the wider political picture","translation":"تصویر سیاسی گسترده تر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000360611.mp3"},{"sentence":"Checks throughout the region revealed a similar picture everywhere.","translation":"بررسی‌ها در سراسر منطقه تصویر مشابهی را در همه جا نشان داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001767488.mp3"},{"sentence":"We were so caught up with the details, we lost sight of the big picture (= the situation considered as a whole ) .","translation":"ما آنقدر درگیر جزئیات بودیم که تصویر بزرگ را از دست دادیم (= وضعیت به عنوان یک کل در نظر گرفته شد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537970.mp3"}]'::jsonb,4),
