('7d707c0c-afaf-56fe-86cc-259109a312b8','0768e8be-4e29-5bb4-99f4-9170eb3c7a83',1,null,null,'spoken & written','to imagine something by making an image in your mind',null,null,'با ساختن یک تصویر در ذهن خود چیزی را تصور کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Tom, picturing the scene, smiled.","translation":"تام در حال تصویر کردن صحنه، لبخند زد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537989.mp3"},{"sentence":"Rob had pictured her as serious, but she wasn’t like that.","translation":"راب او را جدی تصور کرده بود، اما او اینطور نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000360715.mp3"},{"sentence":"I can’t picture him skiing. He’s so clumsy!","translation":"نمی توانم او را در حال اسکی تصور کنم. او خیلی دست و پا چلفتی است!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000360718.mp3"},{"sentence":"Picture what it would be like after a nuclear attack.","translation":"تصور کنید که بعد از یک حمله اتمی چگونه خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537992.mp3"}]'::jsonb,4),
('cd5f762c-fbf2-511e-8b56-20de9f2de9c6','0768e8be-4e29-5bb4-99f4-9170eb3c7a83',2,null,null,'spoken & written','to show someone or something in a photograph, painting, or drawing',null,null,'برای نشان دادن کسی یا چیزی در یک عکس، نقاشی یا طراحی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She is pictured with her mum Christine and sister Kelly.","translation":"او با مادرش کریستین و خواهرش کلی تصویر شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537994.mp3"}]'::jsonb,1),
('2abb47c2-6a2e-5195-a7fa-687c2885b368','0768e8be-4e29-5bb4-99f4-9170eb3c7a83',3,null,null,'spoken & written','to describe something in a particular way',null,null,'برای توصیف چیزی به شیوه ای خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s been pictured as a difficult, demanding woman.","translation":"او به‌عنوان زنی دشوار و سخت‌گیر تصویر شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001537995.mp3"}]'::jsonb,1),
('60fbd911-4b60-55c8-9d63-79f471338aa2','b024867a-90c6-54c3-ae76-8eb46fec0a9f',1,null,null,'spoken & written','made of plastic',null,null,'ساخته شده از پلاستیک','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a plastic spoon","translation":"یک قاشق پلاستیکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000335402.mp3"},{"sentence":"plastic bags","translation":"کیسه های پلاستیکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000335403.mp3"}]'::jsonb,2),
('afd691b2-aec1-5f0f-bc2c-db6ce7731337','b024867a-90c6-54c3-ae76-8eb46fec0a9f',2,null,null,'technical','a plastic substance can be formed into many different shapes and keeps the shape it is formed into until someone changes it',null,null,'یک ماده پلاستیکی را می توان به اشکال مختلف درآورد و شکلی که به آن شکل گرفته است را تا زمانی که کسی آن را تغییر دهد حفظ می کند','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('92071424-cb33-525e-9232-77fbc9ce2761','b024867a-90c6-54c3-ae76-8eb46fec0a9f',3,null,null,'spoken & written','something that is plastic looks or tastes artificial or not natural',null,null,'چیزی که پلاستیکی به نظر می رسد یا طعمی مصنوعی دارد یا طبیعی نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"plastic food","translation":"غذای پلاستیکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000335411.mp3"},{"sentence":"I hate that plastic smile of hers.","translation":"من از لبخند پلاستیکی او متنفرم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000335412.mp3"}]'::jsonb,2),
('9827e470-6a59-50ac-bf3b-cbca3ff49383','6ad2a108-6127-5060-b152-c05f63dae2fc',1,null,null,'spoken & written','a light strong material that is produced by a chemical process , and which can be made into different shapes when it is soft','[ countable, uncountable ]',null,'پلاستیک، پلیمر (ماده)؛ پلاستیکی (پول)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"children’s toys made of plastic","translation":"اسباب بازی های کودکان از پلاستیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000335380.mp3"},{"sentence":"the plastics industry","translation":"صنعت پلاستیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000335381.mp3"}]'::jsonb,2),
('8ac23469-8a09-553d-9d4e-3881366b91b4','6ad2a108-6127-5060-b152-c05f63dae2fc',2,null,null,'informal','small plastic cards that are used to pay for things instead of money','[ uncountable ]',null,'کارت‌های پلاستیکی کوچکی که به‌جای پول برای چیزهایی پرداخت می‌شوند',array['credit cards']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘I haven’t got any cash.’ ‘Don’t worry, I’ll stick it on the plastic (= pay for it using a credit card ) .’","translation":"«من پول نقد ندارم.» «نگران نباش، آن را روی پلاستیک می‌چسبانم (= هزینه آن را با استفاده از کارت اعتباری پرداخت می‌کنم.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000335392.mp3"},{"sentence":"Do they take plastic? (= can you pay using a credit card? )","translation":"پلاستیک می گیرند؟ (= آیا می توانید با استفاده از کارت اعتباری پرداخت کنید؟)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001539059.mp3"}]'::jsonb,2),
('00cd4a45-e885-5606-858e-44ffbbc85806','7b6e496f-e2e2-5c3d-ab6b-9198140d5ab0',1,null,null,'spoken & written','happy or satisfied',null,null,'خشنود، راضی (از)؛ خرسند (شخص)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Your dad will be so pleased.","translation":"بابات خیلی خوشحال میشه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560657.mp3"},{"sentence":"She seemed pleased by the compliment.","translation":"به نظر می رسید از این تعریف خوشحال شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000340050.mp3"},{"sentence":"I could tell they were pleased about the news.","translation":"می توانم بگویم که آنها از این خبر خوشحال بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00675.mp3"},{"sentence":"Gwinn was pleased with the results.","translation":"گوین از نتایج راضی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000340056.mp3"},{"sentence":"That’s wonderful! I’m really pleased for you.","translation":"این فوق العاده است! من واقعا برای شما خوشحالم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560662.mp3"},{"sentence":"Her mother was pleased that she chose a college close to home.","translation":"مادرش از انتخاب کالج نزدیک به خانه خوشحال بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000340059.mp3"},{"sentence":"I’m pleased to tell you that you’ve got the job.","translation":"خوشحالم که به شما بگویم که این کار را دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000340065.mp3"}]'::jsonb,7),
('7e669075-1b85-5832-8981-29af469492a9','7b6e496f-e2e2-5c3d-ab6b-9198140d5ab0',2,null,null,'spoken & written',null,null,'(I’m) pleased to meet you','خشنود، راضی (از)؛ خرسند (شخص)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
