('84e0c89f-4372-58da-a49e-d5227ed839e1','e952d910-aa0c-5b45-a5ea-2fb261f99268',1,null,null,'spoken & written','precise information, details etc are exact , clear, and correct',null,null,'دقیق، مُحکم (اطلاعات)؛ محدود (حس)',array['exact']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"precise sales figures","translation":"ارقام دقیق فروش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568140.mp3"},{"sentence":"It was difficult to get precise information.","translation":"به دست آوردن اطلاعات دقیق دشوار بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568141.mp3"},{"sentence":"‘She’s a lot older than you, isn’t she?’ ‘Fifteen years, to be precise .’","translation":"«او از شما خیلی بزرگتر است، نه؟» «به طور دقیق، پانزده سال.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568142.mp3"}]'::jsonb,3),
('bea8208d-5063-550d-8534-85542e91085a','e952d910-aa0c-5b45-a5ea-2fb261f99268',2,null,null,'spoken & written','used to emphasize that you are referring to an exact thing','[ only before noun ]',null,'برای تأکید بر این که شما دقیقاً به یک چیز اشاره می کنید استفاده می شود',array['exact']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"At that precise moment, her husband walked in.","translation":"در همان لحظه شوهرش وارد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320106.mp3"},{"sentence":"The precise cause of the disease is unknown.","translation":"علت دقیق بیماری ناشناخته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320107.mp3"},{"sentence":"the precise location of the ship","translation":"مکان دقیق کشتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320101.mp3"},{"sentence":"the precise nature of their agreement","translation":"ماهیت دقیق توافق آنها","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568146.mp3"}]'::jsonb,4),
('7d850305-bee3-5d93-992b-872a018f84e4','e952d910-aa0c-5b45-a5ea-2fb261f99268',3,null,null,'spoken & written','someone who is precise is very careful about small details or about the way they behave',null,null,'کسی که دقیق است در مورد جزئیات کوچک یا نحوه رفتار آنها بسیار مراقب است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a precise careful woman","translation":"یک زن دقیق","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568150.mp3"},{"sentence":"with precise movements of his hands","translation":"با حرکات دقیق دستانش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568151.mp3"}]'::jsonb,2),
('4236cfd6-c48b-50f5-8c84-66f02be3b91b','44fa572b-5181-5336-8e49-aea1ebea51aa',1,null,null,'spoken & written','to say that something will happen, before it happens',null,null,'پیش‌بینی کردن، پیش‌گویی کردن (آینده)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Sales were five percent lower than predicted.","translation":"فروش پنج درصد کمتر از پیش بینی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320477.mp3"},{"sentence":"Newspapers predicted that Davis would be re-elected.","translation":"روزنامه ها پیش بینی کردند که دیویس دوباره انتخاب خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320480.mp3"},{"sentence":"It is difficult to predict what the long-term effects of the accident will be.","translation":"پیش بینی اینکه این حادثه چه اثرات بلندمدتی خواهد داشت دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320483.mp3"},{"sentence":"As Liz had predicted , the rumours were soon forgotten.","translation":"همانطور که لیز پیش بینی کرده بود، شایعات به زودی فراموش شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568197.mp3"},{"sentence":"Unemployment is predicted to increase to 700,000 by the end of the year.","translation":"پیش بینی می شود تا پایان سال بیکاری به 700 هزار نفر افزایش یابد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568204.mp3"}]'::jsonb,5),
('08ecda8b-a575-5894-bb72-f880a2ed2e77','f338e8e2-e931-5280-9509-fb9695ce09e8',1,null,null,'spoken & written',null,null,'premises','مقدمه، پیش‌فرض؛ مبنا (استدلال)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('af90bd24-1a14-56ac-ad49-d9c6d35aa1e6','f338e8e2-e931-5280-9509-fb9695ce09e8',2,null,null,'spoken & written','a statement or idea that you accept as true and use as a base for developing other ideas','[ countable ]',null,'بیانیه یا ایده ای که شما آن را درست می پذیرید و به عنوان پایه ای برای توسعه ایده های دیگر استفاده می کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The idea that there is life on other planets is the central premise of the novel.","translation":"این ایده که زندگی در سیارات دیگر وجود دارد، فرض اصلی رمان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568388.mp3"},{"sentence":"the premise that an accused person is innocent until they are proved guilty","translation":"این فرض که فرد متهم تا زمانی که مجرمیت او ثابت نشود بی گناه است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322564.mp3"}]'::jsonb,2),
('2a2984fc-b87b-57b4-ad1b-86a7886ca287','a3372388-d2cf-5f06-a5c2-12fd7240d17c',1,'make something','چیزی درست کن','spoken & written','to make a meal or a substance','[ transitive ]',null,'آماده کردن، آماده‌سازی کردن؛ تهیه کردن (غذا)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Prepare the sauce while the pasta is cooking.","translation":"سس را در حین پختن پاستا آماده کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568668.mp3"},{"sentence":"When we got home, Stephano was busy preparing dinner.","translation":"وقتی به خانه رسیدیم، استفانو مشغول آماده کردن شام بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766187.mp3"},{"sentence":"Health and safety officers will investigate the site and prepare a report.","translation":"افسران ایمنی و بهداشت محل را بررسی کرده و گزارشی تهیه خواهند کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568671.mp3"},{"sentence":"Green set himself the task of preparing a map of this remote area.","translation":"گرین وظیفه تهیه نقشه این منطقه دورافتاده را بر عهده گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568672.mp3"},{"sentence":"Who’s making dinner tonight?","translation":"چه کسی امشب شام درست می کند؟","audio_url":null},{"sentence":"I’ll make the gravy.","translation":"سس را درست میکنم","audio_url":null}]'::jsonb,6),
('54d828b1-0cce-5544-8557-24a98449b333','a3372388-d2cf-5f06-a5c2-12fd7240d17c',2,'make plans/arrangements','برنامه ریزی / ترتیبات','spoken & written','to make plans or arrangements for something that will happen in the future','[ intransitive, transitive ]',null,'برنامه ریزی یا ترتیبی دادن برای چیزی که در آینده اتفاق خواهد افتاد',array['get ready']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The 45-year-old explorer has been preparing for his latest expedition to the Arctic.","translation":"این کاوشگر 45 ساله برای آخرین سفر خود به قطب شمال آماده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322885.mp3"},{"sentence":"Her parents were busy preparing to go on holiday.","translation":"پدر و مادرش مشغول آماده شدن برای رفتن به تعطیلات بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322892.mp3"},{"sentence":"The prosecution wanted more time to prepare their case.","translation":"دادستان خواهان زمان بیشتری برای آماده سازی پرونده خود بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322888.mp3"},{"sentence":"We’re getting ready to move next week.","translation":"ما برای حرکت در هفته آینده آماده می شویم.","audio_url":null}]'::jsonb,4),
('bb37ef05-f15c-55a1-933f-a39cdba1a294','a3372388-d2cf-5f06-a5c2-12fd7240d17c',3,'make something ready','چیزی آماده کن','spoken & written','to make something ready to be used','[ transitive ]',null,'برای ساختن چیزی آماده استفاده','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Prepare the soil, then plant the seedlings eight inches apart.","translation":"خاک را آماده کنید، سپس نهال ها را به فاصله هشت اینچ از هم بکارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020182.mp3"},{"sentence":"Coulthard’s team were up all night preparing the car for the race.","translation":"تیم کولتارد تمام شب را بیدار بودند و ماشین را برای مسابقه آماده می کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568681.mp3"}]'::jsonb,2),
('1e6045a6-3bfc-5d0b-a286-63fcd36d4ac6','a3372388-d2cf-5f06-a5c2-12fd7240d17c',4,'make yourself ready','خودت را آماده کن','spoken & written','to make yourself mentally or physically ready for something that you expect to happen soon','[ transitive ]',null,'تا خود را از نظر ذهنی یا جسمی برای چیزی که انتظار دارید به زودی رخ دهد آماده کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The letter arrived, and we prepared ourselves for bad news.","translation":"نامه رسید و ما خود را برای خبرهای بد آماده کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568684.mp3"},{"sentence":"Can you just give me a couple more moments to prepare myself?","translation":"آیا می توانید فقط چند لحظه دیگر به من فرصت دهید تا خودم را آماده کنم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000322902.mp3"},{"sentence":"The Chicago Bears are busy preparing themselves for the big game.","translation":"خرس های شیکاگو مشغول آماده سازی خود برای بازی بزرگ هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568687.mp3"},{"sentence":"Buy the album, and prepare to be amazed.","translation":"آلبوم را بخرید و آماده شوید تا شگفت زده شوید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568690.mp3"}]'::jsonb,4),
