('edd37d18-23c2-529a-8d26-47595171c843','e814b5d3-4e03-54c7-88e3-03c413afcce2',1,'give','دادن','spoken & written','to give something to someone, for example at a formal or official occasion','[ transitive ]',null,'ارائه کردن، عرضه کردن (رسمی)؛ تقدیم کردن (پیشنهاد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was presented with a bottle of champagne.","translation":"یک بطری شامپاین به او اهدا شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560858.mp3"},{"sentence":"She was presented with an award .","translation":"جایزه ای به او اهدا شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560859.mp3"},{"sentence":"The computer centre presented a cheque for £500 to cancer research.","translation":"مرکز کامپیوتر چکی به مبلغ 500 پوند به تحقیقات سرطان ارائه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560863.mp3"}]'::jsonb,3),
('fdf91182-4d7e-5176-82e0-3ec1ffbc0766','e814b5d3-4e03-54c7-88e3-03c413afcce2',2,'cause something to happen','باعث شود اتفاقی بیفتد','spoken & written','to cause something to happen or exist','[ transitive ]',null,'باعث وقوع یا وجود چیزی شدن','{}'::text[],'{}'::text[],array['present a problem These mountain roads present problems even to experienced drivers.','present difficulties Juggling work and family responsibilities presents difficulties for women.','present a challenge I''m enjoying my new job because it presents an interesting challenge.','present a threat The disease presents a grave threat to the livestock industry.','present an obstacle (= cause a problem that is difficult to deal with or solve ) The lack of money presented a massive obstacle.']::text[],'[{"sentence":"I knew I had presented her with an impossible task.","translation":"می دانستم که کار غیرممکنی را به او تقدیم کرده ام.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560868.mp3"},{"sentence":"Large classes present great problems to many teachers.","translation":"کلاس های بزرگ مشکلات بزرگی را برای بسیاری از معلمان ایجاد می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000324406.mp3"}]'::jsonb,2),
('45c9d768-8f71-540b-bd80-029b45e57dd1','e814b5d3-4e03-54c7-88e3-03c413afcce2',3,null,null,'spoken & written',null,null,'present yourself','ارائه کردن، عرضه کردن (رسمی)؛ تقدیم کردن (پیشنهاد)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('7b3ff1f3-3a4f-5fc5-800c-58d012396a79','e814b5d3-4e03-54c7-88e3-03c413afcce2',4,'description','توضیحات','spoken & written','to show or describe someone or something','[ transitive ]',null,'برای نشان دادن یا توصیف کسی یا چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The artist was determined to present an accurate picture.","translation":"هنرمند مصمم بود تصویری دقیق ارائه دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000324411.mp3"},{"sentence":"We’ll present the information using a chart.","translation":"ما اطلاعات را با استفاده از نمودار ارائه می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560874.mp3"},{"sentence":"Shakespeare presents the hero as a noble man doomed to make mistakes.","translation":"شکسپیر قهرمان را مردی نجیب معرفی می کند که محکوم به اشتباه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560877.mp3"},{"sentence":"The government presents itself as being sensitive to environmental issues.","translation":"دولت خود را نسبت به مسائل زیست محیطی حساس نشان می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002089282.mp3"}]'::jsonb,4),
('bf07c04a-63a3-5032-ac33-d96c4e226722','e814b5d3-4e03-54c7-88e3-03c413afcce2',5,'speech','سخنرانی','spoken & written','to give a speech in which you offer an idea, plan etc to be considered or accepted','[ transitive ]',null,'برای ایراد سخنرانی که در آن ایده، طرح و غیره را ارائه می دهید تا مورد توجه قرار گیرد یا پذیرفته شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Our manager is due to present the report at the end of the month.","translation":"مدیر ما قرار است در پایان ماه گزارش را ارائه دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560879.mp3"},{"sentence":"On January 3 the company will present its plans to the bank.","translation":"در 3 ژانویه این شرکت برنامه های خود را به بانک ارائه خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000324419.mp3"}]'::jsonb,2),
('5730b815-66ee-56da-8c1e-0a6d17efc4c8','e814b5d3-4e03-54c7-88e3-03c413afcce2',6,'document/ticket','سند/بلیت','spoken & written','to show something such as an official document or ticket to someone in an official position','[ transitive ]',null,'برای نشان دادن چیزی مانند یک سند رسمی یا بلیط به کسی که در یک موقعیت رسمی است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You must present your passport to the customs officer.","translation":"باید پاسپورت خود را به مامور گمرک ارائه دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000324424.mp3"}]'::jsonb,1),
('9a118bbf-645b-5255-a83d-4c014652c3d4','e814b5d3-4e03-54c7-88e3-03c413afcce2',7,'theatre/cinema','تئاتر/سینما','spoken & written','to give a performance in a theatre , cinema etc, or broadcast a programme on television or radio','[ transitive ]',null,'اجرای نمایش در تئاتر، سینما و غیره یا پخش برنامه از تلویزیون یا رادیو','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Edinburgh Theatre Company presents ‘The Wind in the Willows’.","translation":"شرکت تئاتر ادینبورگ \"باد در بیدها\" را ارائه می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000324429.mp3"}]'::jsonb,1),
('96930940-b88b-5b2c-8ce7-19a23b8e0725','e814b5d3-4e03-54c7-88e3-03c413afcce2',8,'television/radio','تلویزیون/رادیو','spoken & written','if you present a television or radio programme, you introduce its different parts','[ transitive ]',null,'اگر یک برنامه تلویزیونی یا رادیویی ارائه می دهید، قسمت های مختلف آن را معرفی می کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Thursday’s ‘The Late Show’ was presented by Cynthia Rose.","translation":"برنامه «The Late Show» پنجشنبه توسط سینتیا رز ارائه شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000324436.mp3"}]'::jsonb,1),
('e637b502-a1e1-570c-abdf-6748b98a335b','e814b5d3-4e03-54c7-88e3-03c413afcce2',9,'appearance','ظاهر','spoken & written','to give something or someone a particular appearance or style','[ transitive ]',null,'ظاهر یا سبک خاصی به چیزی یا شخصی دادن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The restaurant likes to present food with style.","translation":"رستوران دوست دارد غذا را با سبک ارائه دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560889.mp3"}]'::jsonb,1),
