('02963e19-613d-5839-b688-2d4a84481db8','e814b5d3-4e03-54c7-88e3-03c413afcce2',13,'illness','بیماری','medical','to show an illness by having a particular symptom (= sign of an illness )','[ intransitive, transitive ]',null,'نشان دادن بیماری با داشتن یک علامت خاص (= نشانه بیماری)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The doctor asked whether any of the children had been presenting any unusual symptoms.","translation":"دکتر پرسید که آیا هیچ یک از کودکان علائم غیرعادی نشان داده اند یا خیر.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002092252.mp3"},{"sentence":"Three of the five patients presented with fever and severe headaches.","translation":"سه نفر از پنج بیمار با تب و سردرد شدید مراجعه کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002092623.mp3"}]'::jsonb,2),
