('6a60fc7f-b563-5bb0-a428-4a2994d53d64','a1293f99-ea76-5c1d-9484-365e5b18971d',4,null,null,'spoken & written',null,null,'for the present','هدیه، پیشکش؛ (زمان حال) حالا','{}'::text[],'{}'::text[],array['give somebody a present He gave everyone a present.','give something as a present I was given this book as a present.','buy somebody a present ( also get somebody a present informal ) I want to buy a present for Lucy but I’m not sure what she’d like. Did you get Bill a birthday present?','get a present (= receive a present ) Children soon learn to enjoy giving presents as well as getting them.','wrap a present She spent the afternoon wrapping Christmas presents.','open/unwrap a present Can we open our presents now?','exchange presents (= give each other a present ) We always exchange Christmas and birthday presents.','a birthday present Thanks for the birthday present.','a Christmas present What would Dad like as a Christmas present?','a wedding present His wedding present to her had been a diamond necklace.']::text[],'[]'::jsonb,0),
('99168caa-1180-5fe6-bad8-37af1d81256a','a69df290-d05d-545d-9ceb-bb93c2c56098',1,null,null,'spoken & written','to think that something is true, although you are not certain','[ transitive ]',null,'فرض کردن، پنداشتن (بدون اطمینان)؛ مزاحم بودن (متکبر)',array['assume']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Each of you will make a speech, I presume?","translation":"فکر می کنم هر کدام از شما سخنرانی خواهید کرد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000288255.mp3"},{"sentence":"‘Are his parents still alive?’ '' I presume so .’","translation":"\"آیا پدر و مادرش هنوز زنده اند؟\" \"من فکر می کنم همینطور است.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583489.mp3"},{"sentence":"I presume we’ll be there by six o''clock.","translation":"فکر می کنم تا ساعت شش آنجا باشیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583495.mp3"},{"sentence":"From the way he talked, I presumed him to be your boss.","translation":"از طرز حرف زدنش تصور می کردم که او رئیس شماست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583498.mp3"},{"sentence":"The temple is presumed to date from the first century BC.","translation":"قدمت این معبد به قرن اول قبل از میلاد می رسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583501.mp3"}]'::jsonb,5),
('88793612-dd8c-51bf-8f45-fd483b2a33f5','a69df290-d05d-545d-9ceb-bb93c2c56098',2,null,null,'spoken & written','to accept something as true until it is shown to not be true, especially in law','[ transitive ]',null,'پذیرفتن چیزی به عنوان حقیقت تا زمانی که ثابت شود که درست نیست، به خصوص در قانون',array['assume']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We must presume innocence until we have evidence of guilt.","translation":"تا زمانی که مدرکی دال بر گناه نداشته باشیم باید بی گناهی را فرض کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000288270.mp3"},{"sentence":"Their nephew was missing, presumed dead.","translation":"برادرزاده آنها گم شده بود و گمان می رفت مرده باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000288273.mp3"}]'::jsonb,2),
('2f94892d-fbd1-5a27-8d1f-bfb937da72ce','a69df290-d05d-545d-9ceb-bb93c2c56098',3,null,null,'formal','to behave without respect or politeness by doing something that you have no right to do','[ intransitive ]',null,'با انجام کاری که حق انجام آن را ندارید بدون احترام یا ادب رفتار کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I would never presume to tell you what to do.","translation":"من هرگز تصور نمی کنم به شما بگویم چه کاری انجام دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583504.mp3"}]'::jsonb,1),
('0780da67-9c0f-59cc-8617-e05ae452ac83','a69df290-d05d-545d-9ceb-bb93c2c56098',4,null,null,'formal','to accept something as being true and base something else on it','[ transitive usually in present tense ]',null,'چیزی را به عنوان حقیقت بپذیریم و چیز دیگری را بر آن بنا کنیم',array['presuppose']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Ancient History course presumes some knowledge of Greek.","translation":"دوره تاریخ باستان مستلزم دانش یونانی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000288288.mp3"},{"sentence":"I presume that someone will be there to meet us when we arrive.","translation":"من حدس می زنم که وقتی به ما رسیدیم، کسی آنجا باشد تا ما را ملاقات کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583507.mp3"}]'::jsonb,2),
('c105ad42-e40f-5b00-9fd2-7caf2e016663','a69df290-d05d-545d-9ceb-bb93c2c56098',5,null,null,'spoken & written',null,null,'presume on/upon somebody’s friendship/generosity etc','فرض کردن، پنداشتن (بدون اطمینان)؛ مزاحم بودن (متکبر)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('3d4b6998-d82f-55ef-a931-767514744b50','a007ee9f-736e-525a-ae76-c543c046c739',1,null,null,'spoken & written','to behave as if something is true when in fact you know it is not, in order to deceive people or for fun','[ intransitive, transitive ]',null,'خود را دروغگو جلوه دادن؛ وانمود کردن؛ مأمور (جعل)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We can’t go on pretending that everything is OK.","translation":"ما نمی توانیم ادامه دهیم وانمود کنیم که همه چیز خوب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583563.mp3"},{"sentence":"Let’s pretend we’re on the Moon.","translation":"بیایید وانمود کنیم که در ماه هستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583564.mp3"},{"sentence":"She pretended not to notice.","translation":"وانمود کرد که متوجه نمی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583568.mp3"},{"sentence":"He’s not asleep – he’s just pretending.","translation":"او خواب نیست - او فقط تظاهر می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000288627.mp3"},{"sentence":"To pretend ignorance of the situation would be irresponsible.","translation":"تظاهر به ناآگاهی از وضعیت غیرمسئولانه خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583572.mp3"},{"sentence":"I can’t marry her and to pretend otherwise would be wrong.","translation":"من نمی توانم با او ازدواج کنم و وانمود کردن در غیر این صورت اشتباه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583573.mp3"}]'::jsonb,6),
('89ffd966-7d4b-598e-8fb7-5a180172ad8f','a007ee9f-736e-525a-ae76-c543c046c739',2,null,null,'spoken & written','to claim that something is true, when it is not','[ transitive usually in negatives ]',null,'ادعا کردن اینکه چیزی درست است، در حالی که اینطور نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I can’t pretend I understand these technical terms (= I admit I do not understand them ) .","translation":"من نمی توانم وانمود کنم که این اصطلاحات فنی را می فهمم (= اعتراف می کنم که آنها را نمی فهمم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583580.mp3"},{"sentence":"The book doesn’t pretend to be for beginners.","translation":"این کتاب وانمود نمی کند که برای مبتدیان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583585.mp3"}]'::jsonb,2),
('a0794a65-6c40-5372-ad47-5916a151067d','05b626f9-c561-5094-b6b7-065ad7487a80',1,null,null,'spoken & written','imaginary or not real – used especially by children',null,null,'خیالی یا غیر واقعی - به ویژه توسط کودکان استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We sang songs around a pretend campfire.","translation":"ما آوازهایی را در اطراف یک آتش سوزی وانمود می‌کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000289091.mp3"}]'::jsonb,1),
('c8b51e8a-13ab-5287-8527-4a278dfb064d','0d75ae39-ebe6-5ae4-bfb7-b65cb135d8a2',1,null,null,'spoken & written','to stop something from happening, or stop someone from doing something',null,null,'جلوگیری کردن، مانع شدن (رخداد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The rules are intended to prevent accidents.","translation":"قوانین برای جلوگیری از حوادث در نظر گرفته شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000289475.mp3"},{"sentence":"His back injury may prevent him from playing in tomorrow’s game.","translation":"مصدومیت کمر او ممکن است مانع از بازی او در بازی فردا شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583661.mp3"},{"sentence":"We were prevented from entering the site.","translation":"از ورود ما به سایت جلوگیری شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583662.mp3"},{"sentence":"Wrap small ornaments in paper to prevent them being damaged.","translation":"زیور آلات کوچک را در کاغذ بپیچید تا آسیب نبیند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583663.mp3"}]'::jsonb,4),
('ead49ae6-cf97-517c-be72-3ea99f40f73e','47b68008-21af-5fc1-bf3d-fff0dcff28a0',1,null,null,'spoken & written','most important','[ usually before noun ]',null,'اصلی، نخستین؛ ابتدایی (دبستان)؛ بدوی (هیئت)',array['main']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Our primary concern is to provide the refugees with food and health care.","translation":"دغدغه اصلی ما تامین غذا و مراقبت های بهداشتی برای پناهندگان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698526.mp3"},{"sentence":"Many of the villagers rely on fishing as their primary source of income.","translation":"بسیاری از روستاییان به ماهیگیری به عنوان منبع اصلی درآمد خود متکی هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001771628.mp3"},{"sentence":"Their primary objective is to make money.","translation":"هدف اصلی آنها کسب درآمد است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698532.mp3"},{"sentence":"Personal safety is of primary importance .","translation":"ایمنی شخصی در درجه اول اهمیت قرار دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000291408.mp3"}]'::jsonb,4),
('65e65dc2-271b-5551-9e08-5f00ecd5ff9f','47b68008-21af-5fc1-bf3d-fff0dcff28a0',2,null,null,'spoken & written','relating to the education of children between 5 and 11 years old','[ only before noun ]',null,'مربوط به آموزش کودکان 5 تا 11 ساله','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a primary teacher","translation":"یک معلم ابتدایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000291418.mp3"},{"sentence":"primary education","translation":"آموزش ابتدایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698537.mp3"},{"sentence":"teaching at primary level","translation":"تدریس در مقطع ابتدایی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000291419.mp3"}]'::jsonb,3),
('25b41f2a-adfe-5890-8f25-25f4b84514ba','47b68008-21af-5fc1-bf3d-fff0dcff28a0',3,null,null,'spoken & written','happening or developing before other things',null,null,'قبل از چیزهای دیگر اتفاق می افتد یا در حال توسعه است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a primary tumour","translation":"یک تومور اولیه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698539.mp3"},{"sentence":"Counselling was given as a primary therapy for depression.","translation":"مشاوره به عنوان درمان اولیه برای افسردگی انجام شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001771632.mp3"}]'::jsonb,2),
