('aae2e76b-1395-5f9d-bf0b-cf89c0adc154','cee7e31e-1c3a-509c-ac4b-be8bf0c33a2b',1,'not for the public','نه برای عموم','spoken & written','for use by one person or group, not for everyone',null,null,'خصوصی، شخصی؛ خصوصی (تدریس)؛ خصوصی (برند)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Morris has a private jet.","translation":"موریس یک جت شخصی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568981.mp3"},{"sentence":"He made some notes for his private use.","translation":"او یادداشت هایی را برای استفاده خصوصی خود نوشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568982.mp3"},{"sentence":"They objected to any form of private property .","translation":"آنها به هر شکلی از مالکیت خصوصی اعتراض کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568983.mp3"}]'::jsonb,3),
('bbf5da40-e6f4-59a6-82a2-ca1b53c30288','cee7e31e-1c3a-509c-ac4b-be8bf0c33a2b',2,'not government','نه دولت','spoken & written','not related to, owned by, or paid for by the government','[ only before noun ]',null,'به دولت مربوط نمی شود، متعلق به آن است یا توسط آن پرداخت می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a private hospital","translation":"یک بیمارستان خصوصی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000293781.mp3"},{"sentence":"There is private ownership of property in a market economy.","translation":"در اقتصاد بازار، مالکیت خصوصی مالکیت وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568988.mp3"},{"sentence":"private education","translation":"آموزش خصوصی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568989.mp3"}]'::jsonb,3),
('61a47b40-df49-58ef-a017-5dfbf4c79856','cee7e31e-1c3a-509c-ac4b-be8bf0c33a2b',3,'for only a few','فقط برای چند نفر','spoken & written','a private meeting, conversation etc involves only two people or a small number of people, and is not for other people to know about',null,null,'یک جلسه خصوصی، مکالمه و غیره فقط شامل دو نفر یا تعداد کمی از افراد می شود و برای افراد دیگر دانستن آن نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I need to have a private discussion with you.","translation":"من باید یک بحث خصوصی با شما داشته باشم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000293775.mp3"},{"sentence":"Are you alone? I just wanted a private word.","translation":"آیا شما تنها هستید؟ فقط یه حرف خصوصی میخواستم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568995.mp3"}]'::jsonb,2),
('e16a6946-2efb-590f-80f6-ae244d05eb28','cee7e31e-1c3a-509c-ac4b-be8bf0c33a2b',4,'secret','راز','spoken & written','private feelings , information, or opinions are personal or secret and not for other people to know about',null,null,'احساسات، اطلاعات یا نظرات خصوصی شخصی یا مخفی هستند و برای دیگران اطلاعی از آن وجود ندارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Jack’s private opinion was that she was selfish.","translation":"نظر خصوصی جک این بود که او خودخواه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000293771.mp3"},{"sentence":"Don’t read that – it’s private.","translation":"آن را نخوانید - خصوصی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568998.mp3"}]'::jsonb,2),
('cdf88235-43fd-5d01-8ef5-f85a7f2a1ee4','cee7e31e-1c3a-509c-ac4b-be8bf0c33a2b',5,'not publicly known','به طور عمومی شناخته نشده است','spoken & written','used about someone who is not known to the public or not working for the government or another organization',null,null,'در مورد کسی که برای مردم شناخته شده نیست یا برای دولت یا سازمان دیگری کار نمی کند استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a private citizen","translation":"یک شهروند خصوصی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569002.mp3"},{"sentence":"The painting was sold to a private collector.","translation":"این نقاشی به یک مجموعه دار خصوصی فروخته شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569003.mp3"},{"sentence":"Seven police and three private individuals needed medical attention.","translation":"هفت پلیس و سه فرد خصوصی به مراقبت های پزشکی نیاز داشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569004.mp3"}]'::jsonb,3),
('016f05cf-0ddb-50a2-a9bb-18ede61e1ecc','cee7e31e-1c3a-509c-ac4b-be8bf0c33a2b',6,'not work','کار نمی کند','spoken & written','separate from and not related to your work or your official position',null,null,'جدا از کار یا موقعیت رسمی شما و غیر مرتبط با آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The president is paying a private visit to Europe.","translation":"رئیس جمهور در سفری خصوصی به اروپا می رود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000293791.mp3"},{"sentence":"He enjoys everything he does in both his professional and his private life .","translation":"او از هر کاری که انجام می دهد هم در زندگی حرفه ای و هم در زندگی خصوصی خود لذت می برد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000293795.mp3"}]'::jsonb,2),
('a70467e5-75f2-524c-8e13-4f54f93fa9cc','cee7e31e-1c3a-509c-ac4b-be8bf0c33a2b',7,'quiet place','جای ساکت','spoken & written','quiet and without a lot of people',null,null,'ساکت و بدون جمعیت زیاد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Why don’t we go upstairs where it’s more private?","translation":"چرا جایی که خصوصی تر است به طبقه بالا نمی رویم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000293800.mp3"}]'::jsonb,1),
('bed912f8-6786-53e0-b54c-507859c8488a','cee7e31e-1c3a-509c-ac4b-be8bf0c33a2b',8,'person','شخص','spoken & written','a private person is one who likes being alone , and does not talk much about their thoughts or feelings','[ only before noun ]',null,'شخص خصوصی کسی است که دوست دارد تنها باشد و زیاد در مورد افکار یا احساسات خود صحبت نمی کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He’s a very private man.","translation":"او یک مرد بسیار خصوصی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000293806.mp3"}]'::jsonb,1),
