('f5fce000-08cc-5c96-917e-d04d7c4c3838','f5a3bd39-8fc1-5b64-9a3e-e2185b5b3be0',1,null,null,'formal','to continue to do something that has already been planned or started',null,null,'ادامه دادن، پیش رفتن (با نقشه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The government was determined to proceed with the election.","translation":"دولت مصمم بود که انتخابات را ادامه دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000295074.mp3"},{"sentence":"Before proceeding further, we must define our terms.","translation":"قبل از ادامه، باید شرایط خود را تعریف کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001835043.mp3"},{"sentence":"They decided to go ahead with the project.","translation":"آنها تصمیم گرفتند که پروژه را ادامه دهند.","audio_url":null}]'::jsonb,3),
