('a72f05d4-3aad-5332-85f6-08087e47c7a7','6944fcda-7017-5663-b4a0-265ea9b6e0ce',9,'feeling','احساس','spoken & written','to imagine that someone else is feeling the same emotions as you','[ transitive ]',null,'تصور کنید که شخص دیگری احساساتی مشابه شما دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You’re projecting your insecurity onto me.","translation":"شما ناامنی خود را به من نشان می دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000299684.mp3"}]'::jsonb,1),
('b5a76384-2abc-5a81-b1c4-65f77df5cca1','6942ba94-7977-5de0-b31f-f6b60e04c1f1',1,null,null,'spoken & written','to tell someone that you will definitely do or provide something or that something will happen','[ intransitive, transitive ]',null,'قول دادن، وعده دادن؛ نوید دادن (بهبود)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Last night the headmaster promised a full investigation.","translation":"دیشب مدیر مدرسه قول بررسی کامل داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583093.mp3"},{"sentence":"She’s promised to do all she can to help.","translation":"او قول داده است که تمام تلاشش را برای کمک انجام دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300185.mp3"},{"sentence":"Hurry up – we promised we wouldn’t be late.","translation":"عجله کنید - ما قول دادیم که دیر نکنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300176.mp3"},{"sentence":"You promised me the car would be ready on Monday.","translation":"به من قول دادی که دوشنبه ماشین آماده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300179.mp3"},{"sentence":"‘Promise me you won’t do anything stupid.’ ‘I promise.’","translation":"\"به من قول بده که هیچ کار احمقانه ای انجام نمی دهی.\" \"قول می دهم.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300182.mp3"},{"sentence":"I’ve promised that book to Ian, I’m afraid.","translation":"من آن کتاب را به ایان قول داده ام، می ترسم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583104.mp3"},{"sentence":"The company promised us a bonus this year.","translation":"این شرکت امسال به ما وعده پاداش داده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300189.mp3"},{"sentence":"‘I’ll be back by 1.00.’ ‘ Promise ?’ ‘Yes! Don’t worry.’","translation":"«تا ساعت 1 برمی‌گردم.» «قول می‌دهی؟» «بله! نگران نباش.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300194.mp3"},{"sentence":"He reappeared two hours later, as promised .","translation":"طبق قولی که داده بود دو ساعت بعد دوباره ظاهر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300201.mp3"}]'::jsonb,9),
('33cc2946-4eca-50d1-859e-7bb97bce496a','6942ba94-7977-5de0-b31f-f6b60e04c1f1',2,null,null,'spoken & written','to show signs of something','[ transitive ]',null,'نشان دادن نشانه هایی از چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Tonight’s meeting promises to be a difficult one.","translation":"جلسه امشب نوید می دهد که جلسه سختی باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300213.mp3"},{"sentence":"dark clouds promising showers later","translation":"ابرهای تیره که بعداً بارندگی را نوید می دهند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300214.mp3"}]'::jsonb,2),
