('14e9a758-16da-5a11-a294-aaf7e1e16225','a203450a-bcb2-5d0d-a7e2-a9f01b20b3bb',4,'sport','ورزش','spoken & written','if a sports team is promoted, they play in a better group of teams the next year',null,null,'اگر یک تیم ورزشی صعود کند، سال بعد در گروه تیم های بهتری بازی می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They have been promoted to the First Division.","translation":"آنها به لیگ دسته اول صعود کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001583167.mp3"}]'::jsonb,1),
('509934d2-5bbb-5cdf-9852-b736a5abd716','a203450a-bcb2-5d0d-a7e2-a9f01b20b3bb',5,'persuade','متقاعد کردن','spoken & written','to try to persuade people to support or use something',null,null,'تلاش برای متقاعد کردن مردم برای حمایت یا استفاده از چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"John Major promoted the idea of a classless society.","translation":"جان میجر ایده جامعه بی طبقه را ترویج کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000300796.mp3"}]'::jsonb,1),
('fdb07c17-adc8-5461-9ee8-690dba65c801','a203450a-bcb2-5d0d-a7e2-a9f01b20b3bb',6,'arrange','ترتیب دهید','spoken & written','to be responsible for arranging a large public event such as a concert or a sports game',null,null,'مسئولیت ترتیب دادن یک رویداد عمومی بزرگ مانند یک کنسرت یا یک بازی ورزشی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('5747b535-8839-5147-b531-bb41d82cfeb7','f8be94d8-33e5-547a-b470-1a55cb9e7374',1,'suggest','پیشنهاد می کند','formal','to suggest something as a plan or course of action','[ transitive ]',null,'پیشنهاد کردن، طرح کردن (ایده)؛ خواستگاری کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The changes were first proposed last year.","translation":"این تغییرات اولین بار در سال گذشته ارائه شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00694.mp3"},{"sentence":"the proposed budget cuts","translation":"کاهش بودجه پیشنهادی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000302976.mp3"},{"sentence":"In his speech he proposed that the UN should set up an emergency centre for the environment.","translation":"او در سخنرانی خود پیشنهاد کرد که سازمان ملل باید یک مرکز اضطراری برای محیط زیست ایجاد کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569407.mp3"},{"sentence":"The report also proposes expanding the airport.","translation":"این گزارش همچنین توسعه فرودگاه را پیشنهاد می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00695.mp3"},{"sentence":"He proposed a compromise to me.","translation":"او به من پیشنهاد سازش داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00696.mp3"},{"sentence":"The idea was first put forward by a German scientist.","translation":"این ایده اولین بار توسط یک دانشمند آلمانی مطرح شد.","audio_url":null}]'::jsonb,6),
('13353b62-edd6-5f62-b0e4-eadf243a8cff','f8be94d8-33e5-547a-b470-1a55cb9e7374',2,'meeting','جلسه','spoken & written','to formally suggest a course of action at a meeting and ask people to vote on it','[ transitive ]',null,'به طور رسمی در یک جلسه یک اقدام را پیشنهاد کنید و از مردم بخواهید که در مورد آن رای دهند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The resolution was proposed by the chairman of the International Committee.","translation":"این قطعنامه توسط رئیس کمیته بین المللی پیشنهاد شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569411.mp3"},{"sentence":"Mr Leesom proposed Mrs Banks for the position of Treasurer (= he suggested formally that she should be the treasurer ) .","translation":"آقای لیسوم خانم بنکس را برای سمت خزانه دار پیشنهاد کرد (= او رسماً پیشنهاد داد که خزانه دار باشد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000302989.mp3"}]'::jsonb,2),
('5ce0b674-b0ec-5ec6-9d0a-924ccfeb4577','f8be94d8-33e5-547a-b470-1a55cb9e7374',3,'theory','نظریه','spoken & written','to suggest an idea, method etc as an answer to a scientific question or as a better way of doing something','[ transitive ]',null,'پیشنهاد یک ایده، روش و غیره به عنوان پاسخ به یک سوال علمی یا به عنوان روشی بهتر برای انجام کاری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A number of theories have been proposed to explain the phenomenon.","translation":"تعدادی نظریه برای توضیح این پدیده ارائه شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569415.mp3"}]'::jsonb,1),
('38f5b717-fd04-56bd-93d1-7227ce1230bf','f8be94d8-33e5-547a-b470-1a55cb9e7374',4,'intend','قصد دارند','formal','to intend to do something','[ transitive ]',null,'قصد انجام کاری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"How does he propose to deal with the situation?","translation":"او چگونه پیشنهاد می کند که با این وضعیت برخورد کند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000303027.mp3"},{"sentence":"We still don’t know how the company proposes raising the money.","translation":"ما هنوز نمی دانیم که این شرکت چگونه پیشنهاد جمع آوری پول را می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000303030.mp3"}]'::jsonb,2),
('011360f1-6cd2-56bd-a6dd-0bcfd740e854','f8be94d8-33e5-547a-b470-1a55cb9e7374',5,'marriage','ازدواج','formal','to ask someone to marry you, especially in a formal way','[ intransitive ]',null,'از کسی بخواهید که با شما ازدواج کند، به خصوص به شکل رسمی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Shaun proposed to me only six months after we met.","translation":"شان تنها شش ماه پس از ملاقات ما از من خواستگاری کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000303005.mp3"}]'::jsonb,1),
('cc6dd47d-bb5a-5392-be40-24fc1b22f331','f8be94d8-33e5-547a-b470-1a55cb9e7374',6,null,null,'spoken & written',null,null,'propose a toast (to somebody)','پیشنهاد کردن، طرح کردن (ایده)؛ خواستگاری کردن','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('998927e0-4d08-5684-8ba2-6d1992ae47dc','54a99dce-4be2-5454-817a-478d300ed663',1,null,null,'spoken & written','to keep someone or something safe from harm , damage , or illness','[ intransitive, transitive ]',null,'محافظت کردن، پشتیبانی کردن (از)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Are we doing enough to protect the environment?","translation":"آیا ما به اندازه کافی برای حفاظت از محیط زیست انجام می دهیم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591832.mp3"},{"sentence":"The cover protects the machine from dust.","translation":"پوشش دستگاه از گرد و غبار محافظت می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591835.mp3"},{"sentence":"Physical exercise can protect you against heart disease.","translation":"ورزش بدنی می تواند از شما در برابر بیماری قلبی محافظت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000304481.mp3"},{"sentence":"Waxing your car will help protect against rust.","translation":"واکس زدن خودرو به محافظت در برابر زنگ زدگی کمک می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000304484.mp3"}]'::jsonb,4),
('97f69514-3419-52aa-9a5a-103ce888a0fb','54a99dce-4be2-5454-817a-478d300ed663',2,null,null,'spoken & written','if an insurance company protects your home, car , life etc, it agrees to pay you money if things are stolen or damaged or you are hurt or killed','[ transitive ]',null,'اگر یک شرکت بیمه از خانه، ماشین، زندگی شما و غیره محافظت می کند، موافقت می کند که اگر چیزهایی به سرقت رفته یا آسیب ببینند یا آسیب ببینند یا کشته شوند، به شما پول بپردازند.',array['cover']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Unemployment insurance means that you are partially protected if you lose your job.","translation":"بیمه بیکاری به این معنی است که در صورت از دست دادن شغل خود تا حدی از شما محافظت می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591841.mp3"}]'::jsonb,1),
('acf0dfa1-ba82-5865-89b6-17a31461586e','54a99dce-4be2-5454-817a-478d300ed663',3,null,null,'spoken & written','to help the industry and trade of your own country by taxing or restricting foreign goods','[ transitive ]',null,'برای کمک به صنعت و تجارت کشور خود با اعمال مالیات یا محدود کردن کالاهای خارجی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('26fd81f1-85e5-5cd1-a55e-73dcd2676641','8c42c9cf-ffe6-5ac9-953c-f3d02ca9af8e',1,null,null,'spoken & written','something that you do to show publicly that you think that something is wrong and unfair , for example taking part in big public meetings , refusing to work, or refusing to buy a company’s products','[ countable, uncountable ]',null,'اعتراض، انتقاد (تظاهرات)؛ اعتراض (سخن)؛ اعتراض (کار)','{}'::text[],'{}'::text[],array['hold/stage/mount a protest Opponents of the plan have staged several protests.','lead to/spark (off) protests (= cause them ) The arrests sparked off violent street protests.','organize a protest She organized a protest outside the store.','protests erupt (= start suddenly ) Massive protests erupted across the country.','a public/popular protest The announcement led to widespread public protests.','political protest Lee spent five years in prison for his involvement in political protest.','a peaceful protest Some 5,000 students and others began a peaceful protest.','a violent/angry protest Three people died yesterday in violent protests against the war.','a mass protest (= one involving a lot of people ) There were mass protests in the capital.','a massive protest They reacted to the king’s forced abdication with massive public protests.','a student protest Student protests were crushed by police.','a street protest There was a ban on street protests.','an anti-government protest Religious leaders continued to lead anti-government protests.','a protest group/movement Students at the heart of the protest movement have called for a general strike.','a protest march They staged a protest march through the city’s streets.','a protest rally (= a large outdoor public meeting to protest about something ) A protest rally in the capital was attended by about 400 people.']::text[],'[{"sentence":"Students held a protest march against the war.","translation":"دانشجویان در اعتراض به جنگ راهپیمایی کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001264.mp3"},{"sentence":"Five thousand employees came out on strike in protest at the poor working conditions.","translation":"پنج هزار کارمند در اعتراض به شرایط بد کار دست به اعتصاب زدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020191.mp3"}]'::jsonb,2),
('2ccca2cc-dd33-5dbd-a7d9-fead140d9f9c','8c42c9cf-ffe6-5ac9-953c-f3d02ca9af8e',2,null,null,'spoken & written','words or actions that show that you do not want someone to do something or that you dislike something very much','[ countable ]',null,'کلمات یا اعمالی که نشان می‌دهد نمی‌خواهید کسی کاری را انجام دهد یا کاری را خیلی دوست ندارید','{}'::text[],'{}'::text[],array['hold/stage/mount a protest Opponents of the plan have staged several protests.','lead to/spark (off) protests (= cause them ) The arrests sparked off violent street protests.','organize a protest She organized a protest outside the store.','protests erupt (= start suddenly ) Massive protests erupted across the country.','a public/popular protest The announcement led to widespread public protests.','political protest Lee spent five years in prison for his involvement in political protest.','a peaceful protest Some 5,000 students and others began a peaceful protest.','a violent/angry protest Three people died yesterday in violent protests against the war.','a mass protest (= one involving a lot of people ) There were mass protests in the capital.','a massive protest They reacted to the king’s forced abdication with massive public protests.','a student protest Student protests were crushed by police.','a street protest There was a ban on street protests.','an anti-government protest Religious leaders continued to lead anti-government protests.','a protest group/movement Students at the heart of the protest movement have called for a general strike.','a protest march They staged a protest march through the city’s streets.','a protest rally (= a large outdoor public meeting to protest about something ) A protest rally in the capital was attended by about 400 people.']::text[],'[{"sentence":"I turned off the TV, despite loud protests from the kids.","translation":"با وجود اعتراض شدید بچه ها تلویزیون را خاموش کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942014.mp3"},{"sentence":"He accepted his punishment without protest.","translation":"او بدون اعتراض مجازات خود را پذیرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942020.mp3"},{"sentence":"She ignored his protests and walked away.","translation":"اعتراضات او را نادیده گرفت و رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942021.mp3"},{"sentence":"The programme caused a storm of protest (= a lot of angry protest ) .","translation":"برنامه طوفان اعتراضی به پا کرد (= اعتراض خشمگین زیاد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942025.mp3"},{"sentence":"The announcement was met with howls of protest .","translation":"این اعلامیه با زوزه های اعتراضی مواجه شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001942030.mp3"}]'::jsonb,5),
('13d57950-f242-5bca-b5bf-44b58e8b5acf','8c42c9cf-ffe6-5ac9-953c-f3d02ca9af8e',3,null,null,'spoken & written',null,null,'do something under protest','اعتراض، انتقاد (تظاهرات)؛ اعتراض (سخن)؛ اعتراض (کار)','{}'::text[],'{}'::text[],array['hold/stage/mount a protest Opponents of the plan have staged several protests.','lead to/spark (off) protests (= cause them ) The arrests sparked off violent street protests.','organize a protest She organized a protest outside the store.','protests erupt (= start suddenly ) Massive protests erupted across the country.','a public/popular protest The announcement led to widespread public protests.','political protest Lee spent five years in prison for his involvement in political protest.','a peaceful protest Some 5,000 students and others began a peaceful protest.','a violent/angry protest Three people died yesterday in violent protests against the war.','a mass protest (= one involving a lot of people ) There were mass protests in the capital.','a massive protest They reacted to the king’s forced abdication with massive public protests.','a student protest Student protests were crushed by police.','a street protest There was a ban on street protests.','an anti-government protest Religious leaders continued to lead anti-government protests.','a protest group/movement Students at the heart of the protest movement have called for a general strike.','a protest march They staged a protest march through the city’s streets.','a protest rally (= a large outdoor public meeting to protest about something ) A protest rally in the capital was attended by about 400 people.']::text[],'[]'::jsonb,0),
('9dd5ede3-78a5-5e71-8642-5e3bf86ec391','98983322-efa8-5b91-a284-b5c76aee527f',1,null,null,'spoken & written','to come together to publicly express disapproval or opposition to something','[ intransitive, transitive ]',null,'دور هم جمع شدن تا علناً مخالفت یا مخالفت با چیزی را ابراز کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Thousands of people blocked the street, protesting against the new legislation.","translation":"هزاران نفر در اعتراض به قانون جدید خیابان را مسدود کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000305354.mp3"},{"sentence":"Students protested the decision.","translation":"دانشجویان به این تصمیم اعتراض کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000305360.mp3"}]'::jsonb,2),
('fb63cbc3-6839-584d-8839-2cc3b8c0a7f7','98983322-efa8-5b91-a284-b5c76aee527f',2,null,null,'spoken & written','to say that you strongly disagree with or are angry about something because you think it is wrong or unfair','[ intransitive, transitive ]',null,'گفتن اینکه به شدت با چیزی مخالف هستید یا از آن عصبانی هستید زیرا فکر می کنید اشتباه یا ناعادلانه است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘I don’t see why I should take the blame for this!’ she protested.","translation":"او اعتراض کرد: «نمی‌دانم چرا باید این موضوع را مقصر بدانم!»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591944.mp3"},{"sentence":"Clive protested that he hadn’t been given enough time to do everything.","translation":"کلایو اعتراض کرد که به او زمان کافی برای انجام همه کارها داده نشده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591947.mp3"}]'::jsonb,2),
('0db7eaaf-9365-51f0-9f4d-3cf981f93e6e','98983322-efa8-5b91-a284-b5c76aee527f',3,null,null,'spoken & written','to state very firmly that something is true, when other people do not believe you','[ transitive ]',null,'با قاطعیت بیان کنید که چیزی درست است، وقتی دیگران شما را باور ندارند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Sarah protested that she wasn’t Mick’s girlfriend.","translation":"سارا اعتراض کرد که او دوست دختر میک نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591950.mp3"},{"sentence":"Years later, he is still protesting his innocence .","translation":"سال ها بعد، او همچنان به بی گناهی خود اعتراض می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591951.mp3"}]'::jsonb,2),
('0c899f29-757e-5553-98ea-84815bba007e','cc22a4f0-3e72-527e-9975-d52c5dc2ab93',1,null,null,'spoken & written','to give something to someone or make it available to them, because they need it or want it',null,null,'فراهم کردن، در دسترس گذاشتن (برای)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Tea and biscuits will be provided.","translation":"چای و بیسکویت ارائه خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001592095.mp3"},{"sentence":"The hotel provides a shoe-cleaning service for guests.","translation":"این هتل خدمات تمیز کردن کفش را برای مهمانان ارائه می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000305772.mp3"},{"sentence":"The project is designed to provide young people with work.","translation":"این پروژه به منظور ایجاد فرصت شغلی برای جوانان طراحی شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000305775.mp3"}]'::jsonb,3),
('db82a0de-eff4-5d8f-a718-3f09b8d91910','cc22a4f0-3e72-527e-9975-d52c5dc2ab93',2,null,null,'spoken & written','to produce something useful as a result',null,null,'برای تولید چیزی مفید در نتیجه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We are hoping the enquiry will provide an explanation for the accident.","translation":"امیدواریم تحقیقات در مورد این حادثه توضیحی ارائه کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000305782.mp3"},{"sentence":"The search provided the police with several vital clues.","translation":"جستجو چندین سرنخ حیاتی در اختیار پلیس قرار داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000305785.mp3"}]'::jsonb,2),
('9eb60405-be6b-5525-b33a-1ad3396cf638','cc22a4f0-3e72-527e-9975-d52c5dc2ab93',3,null,null,'spoken & written',null,null,'provide that','فراهم کردن، در دسترس گذاشتن (برای)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ccd42c0c-6a17-5f95-baf0-607579c309d0','59aee951-29e9-51d8-b646-f0c6d18519e6',1,null,null,'spoken & written','to arrange for a book , magazine etc to be written, printed , and sold','[ transitive ]',null,'چاپ کردن، منتشر کردن (کتاب)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The first edition was published in 1765.","translation":"اولین نسخه در سال 1765 منتشر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561828.mp3"},{"sentence":"They are publishing the dictionary on CD-ROM.","translation":"آنها فرهنگ لغت را روی سی دی رام منتشر می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001561829.mp3"}]'::jsonb,2),
('482cc10e-e72a-54ab-9beb-7c4ed640902f','59aee951-29e9-51d8-b646-f0c6d18519e6',2,null,null,'spoken & written','if a newspaper or magazine publishes a letter , article etc, it prints it for people to read','[ transitive ]',null,'اگر روزنامه یا مجله ای نامه، مقاله و غیره منتشر می کند، آن را چاپ می کند تا مردم بخوانند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We love reading your letters and we try to publish as many as possible.","translation":"ما عاشق خواندن نامه های شما هستیم و سعی می کنیم تا جایی که ممکن است بیشتر منتشر کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000270777.mp3"}]'::jsonb,1),
('ba3e4ba6-1b42-55a6-ab2a-a509d75dfd1c','59aee951-29e9-51d8-b646-f0c6d18519e6',3,null,null,'spoken & written','to make official information such as a report available for everyone to read','[ transitive ]',null,'تا اطلاعات رسمی مانند گزارش در دسترس همگان قرار گیرد تا مطالعه کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The latest unemployment figures will be published tomorrow.","translation":"آخرین آمار بیکاری فردا منتشر می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000270782.mp3"}]'::jsonb,1),
('6f313df9-b065-5494-987b-d610499f37de','59aee951-29e9-51d8-b646-f0c6d18519e6',4,null,null,'spoken & written','if a writer , musician etc publishes their work, they arrange for it to be printed and sold','[ intransitive, transitive ]',null,'اگر نویسنده، نوازنده و غیره کار خود را منتشر کند، ترتیب چاپ و فروش آن را می دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"University teachers must publish regularly to gain promotion.","translation":"معلمان دانشگاه باید به طور منظم منتشر کنند تا ارتقا پیدا کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766556.mp3"}]'::jsonb,1),
('6de75670-b87c-5f85-95a3-90c60f53ccd2','59aee951-29e9-51d8-b646-f0c6d18519e6',5,null,null,'spoken & written',null,null,'publish and be damned','چاپ کردن، منتشر کردن (کتاب)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('6d24baae-b4f4-5a25-8dbb-f41acccaf8a7','79379902-5140-5bd5-93ed-057ebd1584a2',1,null,null,'spoken & written','a hot sweet dish , made from cake , rice , bread etc with fruit , milk , or other sweet things added',null,null,'پودینگ، دسر (خوراکی)؛ پودینگ (خمیر)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('71b752d6-fd14-5257-a30e-3276abfab69f','79379902-5140-5bd5-93ed-057ebd1584a2',2,null,null,'spoken & written','a thick sweet creamy dish, usually made with milk, eggs , sugar , and flour , and served cold',null,null,'یک غذای خامه ای شیرین غلیظ که معمولا با شیر، تخم مرغ، شکر و آرد درست می شود و سرد سرو می شود.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"chocolate pudding","translation":"پودینگ شکلاتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000273454.mp3"}]'::jsonb,1),
('c624dbf2-e4cf-58cd-b5e4-baccefba890f','79379902-5140-5bd5-93ed-057ebd1584a2',3,null,null,'spoken & written','a sweet dish served at the end of a meal',null,'dessert','یک غذای شیرین که در پایان غذا سرو می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There’s ice cream for pudding.","translation":"بستنی برای پودینگ وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000273461.mp3"}]'::jsonb,1),
('0d91815e-7ed4-5e5a-af9a-74e81b75a373','79379902-5140-5bd5-93ed-057ebd1584a2',4,null,null,'spoken & written','a hot dish made of a mixture of flour, fat etc, with meat or vegetables inside',null,null,'یک غذای داغ از مخلوط آرد، چربی و غیره با گوشت یا سبزیجات در داخل','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"steak and kidney pudding","translation":"استیک و پودینگ کلیه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000273471.mp3"}]'::jsonb,1),
('c3d994aa-4bec-5241-b0c8-9cdbb001479e','bd0f0542-4017-5a2c-a15c-fb324ea6f7d2',1,null,null,'spoken & written','the purpose of something is what it is intended to achieve','[ countable ]',null,'هدف، منظور؛ نقش (کار)؛ نیت (دروغین)','{}'::text[],'{}'::text[],array['the main/primary purpose The main purpose of our trip to Arran was to see golden eagles.','the sole purpose I used to bake cakes for the sole purpose of giving them away.','the real purpose What was the real purpose of their visit?','the whole purpose (= used for emphasis ) The whole purpose of running a business is to make money.','something’s original purpose The building is no longer needed for its original purpose.','a useful purpose Nuclear weapons serve no useful purpose and should be banned.','a practical purpose These materials are too fine to have a practical purpose in daily life.','a dual purpose (= two purposes ) A dog can fulfil a dual purpose by providing both company and security.','a common purpose (= one that people share ) We were bound together by a common purpose.','a specific/particular purpose Training is the acquisition of knowledge and skills for a specific purpose.','for political/military/educational/medicinal etc purposes This technology could be used for military purposes.','for business/research etc purposes About one in five of all trips are made for business purposes.','have a purpose A meeting should have a clear purpose.','serve/fulfil a purpose (= be used in a particular way ) The building must have served a religious purpose. Many old school buildings are no longer suitable for fulfilling their original purpose.','achieve your purpose (= achieve what you wanted to achieve ) She had achieved her purpose, at least in part.']::text[],'[{"sentence":"The purpose of this meeting is to elect a new chairman.","translation":"هدف از این جلسه انتخاب رئیس جدید است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000279616.mp3"},{"sentence":"What is the purpose of your visit?","translation":"هدف شما از بازدید چیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000279617.mp3"},{"sentence":"The purpose of conducting a business is to make money.","translation":"هدف از راه اندازی کسب و کار کسب درآمد است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843429.mp3"},{"sentence":"Troops were sent solely for the purpose of assisting refugees.","translation":"نیروها صرفاً برای کمک به پناهندگان اعزام شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843432.mp3"},{"sentence":"It should be legitimate to use cannabis for medical purposes.","translation":"استفاده از حشیش برای اهداف پزشکی باید مشروع باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843446.mp3"},{"sentence":"The protection of children is the primary purpose of this legislation.","translation":"حمایت از کودکان هدف اصلی این قانون است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843436.mp3"},{"sentence":"It would serve no useful purpose to re-open the investigation.","translation":"بازگشایی تحقیقات هیچ هدف مفیدی ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843470.mp3"}]'::jsonb,7),
('0110e920-eae1-5636-b878-5ce38b523009','bd0f0542-4017-5a2c-a15c-fb324ea6f7d2',2,null,null,'spoken & written','a plan or aim','[ countable ]',null,'یک برنامه یا هدف','{}'::text[],'{}'::text[],array['the main/primary purpose The main purpose of our trip to Arran was to see golden eagles.','the sole purpose I used to bake cakes for the sole purpose of giving them away.','the real purpose What was the real purpose of their visit?','the whole purpose (= used for emphasis ) The whole purpose of running a business is to make money.','something’s original purpose The building is no longer needed for its original purpose.','a useful purpose Nuclear weapons serve no useful purpose and should be banned.','a practical purpose These materials are too fine to have a practical purpose in daily life.','a dual purpose (= two purposes ) A dog can fulfil a dual purpose by providing both company and security.','a common purpose (= one that people share ) We were bound together by a common purpose.','a specific/particular purpose Training is the acquisition of knowledge and skills for a specific purpose.','for political/military/educational/medicinal etc purposes This technology could be used for military purposes.','for business/research etc purposes About one in five of all trips are made for business purposes.','have a purpose A meeting should have a clear purpose.','serve/fulfil a purpose (= be used in a particular way ) The building must have served a religious purpose. Many old school buildings are no longer suitable for fulfilling their original purpose.','achieve your purpose (= achieve what you wanted to achieve ) She had achieved her purpose, at least in part.']::text[],'[{"sentence":"Nick had no particular purpose in mind when he started.","translation":"نیک هنگام شروع کار هیچ هدف خاصی در ذهن نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843460.mp3"},{"sentence":"Attending the race was not my purpose in coming to Indianapolis.","translation":"حضور در مسابقه هدف من از آمدن به ایندیاناپولیس نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843466.mp3"},{"sentence":"He came here with the purpose of carrying out the attack.","translation":"او با هدف انجام این حمله به اینجا آمد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843433.mp3"}]'::jsonb,3),
('0503067b-1b73-579d-8aa1-30f5943032ec','bd0f0542-4017-5a2c-a15c-fb324ea6f7d2',3,null,null,'spoken & written',null,null,'for ... purposes','هدف، منظور؛ نقش (کار)؛ نیت (دروغین)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
