('4779fdd1-ebe8-5c38-8b6a-fcd20c2b8e00','bd0f0542-4017-5a2c-a15c-fb324ea6f7d2',5,'feeling','احساس','spoken & written','a feeling of determination to achieve things in life','[ uncountable ]',null,'احساس عزم برای دستیابی به چیزهایی در زندگی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s so important to have a sense of purpose that it underlies human happiness.","translation":"داشتن حس هدف آنقدر مهم است که زیربنای خوشبختی انسان باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000279646.mp3"},{"sentence":"My football career was over and I had no purpose in life .","translation":"فوتبال من تمام شده بود و هیچ هدفی در زندگی نداشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843479.mp3"},{"sentence":"He possessed great strength of purpose .","translation":"او قدرت هدف زیادی داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001843483.mp3"}]'::jsonb,3),
