('be54b539-f8c0-5350-8f66-9f871e53b8f1','226491b2-4d5d-5910-bb8d-120434bcba3c',1,'have a right','حق دارند','spoken & written','to have the right to have or do something, or to give someone this right','[ intransitive, transitive ]',null,'واجد شرایط بودن؛ واجد شرایط کردن؛ دروغ زدن (بی‌معنا)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Free school lunches are given to children who qualify.","translation":"ناهار رایگان مدرسه به کودکان واجد شرایط داده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569638.mp3"},{"sentence":"You may qualify for unemployment benefit.","translation":"شما ممکن است واجد شرایط دریافت مزایای بیکاری باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000464661.mp3"},{"sentence":"Membership qualifies you for a discount on purchases.","translation":"عضویت شما را واجد شرایط تخفیف در خرید می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569641.mp3"}]'::jsonb,3),
('8167ac13-b3de-5ff4-be96-20c3b6bd603a','226491b2-4d5d-5910-bb8d-120434bcba3c',2,'pass exam','قبولی در امتحان','spoken & written','to pass an examination or finish a course of study that you need in order to do something','[ intransitive ]',null,'برای قبولی در امتحان یا اتمام دوره تحصیلی که برای انجام کاری به آن نیاز دارید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I finally qualified as a pilot.","translation":"بالاخره صلاحیت خلبانی را گرفتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000464651.mp3"},{"sentence":"After qualifying, doctors spend at least two years working in hospitals.","translation":"پس از صلاحیت، پزشکان حداقل دو سال را در بیمارستان ها کار می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000464652.mp3"}]'::jsonb,2),
('fca8498e-4879-568b-8e67-9d39f561f6e5','226491b2-4d5d-5910-bb8d-120434bcba3c',3,'be considered something','چیزی در نظر گرفته شود','spoken & written','to have all the necessary qualities to be considered to be a particular thing','[ intransitive ]',null,'داشتن تمام صفات لازم برای اینکه یک چیز خاص در نظر گرفته شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It doesn’t qualify as a date if you bring your children with you.","translation":"اگر فرزندان خود را با خود بیاورید به عنوان یک تاریخ واجد شرایط نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000464681.mp3"}]'::jsonb,1),
('9d2241b9-34c2-56eb-b173-1dac117fc44a','226491b2-4d5d-5910-bb8d-120434bcba3c',4,'give somebody skills/knowledge','به کسی مهارت/دانش بدهید','spoken & written','if something qualifies you to do something, you have the necessary skills , knowledge , ability etc to do it','[ transitive ]',null,'اگر چیزی شما را واجد شرایط انجام کاری می‌کند، مهارت‌ها، دانش، توانایی و غیره لازم برای انجام آن را دارید.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Fluency in three languages qualifies her for work in the European Parliament.","translation":"تسلط به سه زبان او را واجد شرایط کار در پارلمان اروپا می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000464670.mp3"},{"sentence":"The certificate qualifies you to work as a dental assistant.","translation":"این گواهی به شما صلاحیت کار به عنوان دستیار دندانپزشک را می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569646.mp3"}]'::jsonb,2),
('0bc22d26-c292-5c81-a458-47c8dad7890b','226491b2-4d5d-5910-bb8d-120434bcba3c',5,'sport','ورزش','spoken & written','to reach the necessary standard to enter or continue in a competition or sports event','[ intransitive ]',null,'رسیدن به استاندارد لازم برای ورود یا ادامه در یک مسابقه یا رویداد ورزشی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She qualified for a spot on the U.S. Olympic speed skating team.","translation":"او برای یک مقام در تیم اسکیت سرعت المپیک ایالات متحده واجد شرایط شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569649.mp3"}]'::jsonb,1),
('6fddbdde-fc84-5a9a-9403-aff9bf14f787','226491b2-4d5d-5910-bb8d-120434bcba3c',6,'add something','چیزی اضافه کن','spoken & written','to add to something that has already been said, in order to limit its effect or meaning','[ transitive ]',null,'افزودن به چیزی که قبلاً گفته شد تا تأثیر یا معنای آن را محدود کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Could I just qualify that last statement?","translation":"آیا می توانم فقط آن جمله آخر را واجد شرایط کنم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000464697.mp3"}]'::jsonb,1),
('7866450c-0e75-5ebf-922a-d730dc54320d','226491b2-4d5d-5910-bb8d-120434bcba3c',7,'grammar','دستور زبان','spoken & written','if a word or phrase qualifies another word or phrase, it limits or adds to the meaning of it','[ transitive ]',null,'اگر کلمه یا عبارتی برای کلمه یا عبارت دیگری واجد شرایط باشد، معنای آن را محدود یا بر آن می افزاید','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('31257a9d-80e9-5466-9df2-bca82e254ddd','58198aea-8ee8-58c3-b4d6-92709abc643b',1,null,null,'spoken & written','how good or bad something is','[ countable, uncountable ]',null,'کیفیت، مرغوبیت؛ ویژگی (فرد)؛ کیفیت (صدا)','{}'::text[],'{}'::text[],array['good/high I was impressed that the quality of their work was so high.','poor/low The magazine is printed on low quality paper.','excellent/outstanding The T-shirts are only $10 and the quality is excellent.','superior formal (= good or better quality ) These speakers offer superior quality sound.','top quality Our chef uses only top quality ingredients.','water/air quality Scientists took samples to test the water quality.','sound quality I apologise for the poor sound quality of this recording.','picture quality ( also image quality ) Does this type of TV set have a better picture quality?','improve/enhance the quality The measures will improve the quality of the water in the river.','affect the quality Lack of sleep started to affect the quality of his work.','test/check/monitor the quality The equipment is used to monitor the city’s air quality.','maintain the quality Staffing problems made it difficult to maintain the quality of the service.','the quality goes up/down I think the quality has gone down over the years.','the quality suffers (= it is badly affected by something ) The picture quality suffers if the signal isn’t digital.','quality standards Greater investment is needed to meet the European Union’s strict quality standards.']::text[],'[{"sentence":"Much of the land was of poor quality.","translation":"بسیاری از زمین ها کیفیت پایینی داشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001569674.mp3"},{"sentence":"Use only high quality ingredients.","translation":"فقط از مواد با کیفیت بالا استفاده کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000465408.mp3"},{"sentence":"The quality of the water is reasonably good.","translation":"کیفیت آب نسبتا خوب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001273.mp3"}]'::jsonb,3),
