ality.']::text[],'[]'::jsonb,0),
('f97ba9df-c0c9-56d3-b5b9-af39d5f75caa','d9258319-b581-5044-8588-f93b28cce694',3,null,null,'spoken & written','the fact that something exists or is happening','[ uncountable ]',null,'این واقعیت که چیزی وجود دارد یا در حال وقوع است','{}'::text[],'{}'::text[],array['the harsh/grim/stark reality (= conditions that are really very bad ) We want to protect our children from the harsh reality of our violent world.','political/social/economic realities He''s ignoring political realities.','face reality (= accept it ) It''s painful, but you have to face reality.','confront a reality (= consider or deal with it ) They had to confront some unpleasant realities about themselves.','ignore a reality They are ignoring the reality of Arab politics.','wake up to reality (= realize what is happening or real ) Well, they need to wake up to reality.','lose touch with reality (= no longer know about ordinary things or what is possible ) If all you have is the show-business world, you kind of lose touch with reality.','escape from reality The programmes help viewers escape from reality.','bring somebody back to reality (= make them realize what is happening around them or true ) She was brought back to reality by the pain in her ankle.','become a reality (= really happen, after being hoped for, feared, etc by someone ) Last June, her longed-for baby finally became a reality.','reflect reality (= match or show what is really happening or true ) Do these novels accurately reflect contemporary reality?','bear no relation to reality (= not match what is really happening or true ) His vision of European politics bears no relation to reality.','be divorced from reality (= not connected in any way to what is really happening ) His ideas are completely divorced from reality.','a dose of reality (= an experience of what things are really like ) I got my first dose of reality when I reported to work at my new job.','somebody''s grasp of reality (= their understanding of reality ) They portrayed her as a sick woman with only a tenuous grasp of reality.']::text[],'[{"sentence":"She had never accepted the reality of her pregnancy.","translation":"او هرگز واقعیت بارداری خود را قبول نکرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001770461.mp3"}]'::jsonb,1),
('ca860ff6-3395-57da-8c16-290f564b3236','ee79b10c-09b8-50e2-97cc-ae2384f1d972',1,'understand','درک کنند','spoken & written','to know and understand something, or suddenly begin to understand it',null,null,'دریافتن، فهمیدن؛ تحقق یافتن (آرزو)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I suddenly realized that the boy was crying.","translation":"ناگهان متوجه شدم پسر در حال گریه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604523.mp3"},{"sentence":"Do you realize you’re an hour late?","translation":"آیا متوجه هستید که یک ساعت تاخیر دارید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000483789.mp3"},{"sentence":"I’m sorry, I didn’t realize who you were.","translation":"ببخشید نفهمیدم کی هستی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604526.mp3"},{"sentence":"It took us a while to realize the extent of the tragedy.","translation":"مدتی طول کشید تا متوجه وسعت فاجعه شویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604527.mp3"},{"sentence":"It was only later that I realized my mistake.","translation":"بعدها بود که متوجه اشتباهم شدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604528.mp3"},{"sentence":"Nobody realizes how important this is.","translation":"هیچ کس متوجه نیست که این چقدر مهم است.","audio_url":null},{"sentence":"Now I’m a parent, I’m realizing what my parents went through.","translation":"حالا من یک پدر و مادر هستم، دارم متوجه می شوم که پدر و مادرم چه چیزی را پشت سر گذاشته اند.","audio_url":null}]'::jsonb,7),
('3548a417-8618-57e7-a54a-3d9d08fe9a27','ee79b10c-09b8-50e2-97cc-ae2384f1d972',2,'achieve','به دست آوردن','formal','to achieve something that you were hoping to achieve',null,null,'برای رسیدن به چیزی که به آن امیدوار بودید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She never realized her ambition of winning an Olympic gold medal.","translation":"او هرگز به جاه طلبی خود برای کسب مدال طلای المپیک پی نبرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000483815.mp3"},{"sentence":"a young singer who has not yet realized her full potential (= achieved as much as she can achieve )","translation":"خواننده جوانی که هنوز پتانسیل کامل خود را به دست نیاورده است (= تا جایی که می تواند به دست آورد)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604535.mp3"}]'::jsonb,2),
('81a7953b-8a18-5ca2-9823-ce32dd02c74d','ee79b10c-09b8-50e2-97cc-ae2384f1d972',3,null,null,'spoken & written',null,null,'somebody’s worst fears were realized','دریافتن، فهمیدن؛ تحقق یافتن (آرزو)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('a1cbecec-95f6-5da2-8925-d0222faea508','ee79b10c-09b8-50e2-97cc-ae2384f1d972',4,'money','پول','formal','to obtain or earn an amount of money',null,null,'برای به دست آوردن یا به دست آوردن مقداری پول','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The campaign realized $5000.","translation":"این کمپین 5000 دلار دریافت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000483827.mp3"},{"sentence":"We realized a small profit on the sale of the house.","translation":"از فروش خانه متوجه سود ناچیزی شدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604542.mp3"}]'::jsonb,2),
('b9ddb642-5619-5c70-b5d8-b7bd99576295','f7d9fdbb-3464-5eb3-915a-fe15d73ab1e1',1,null,null,'spoken & written','a piece of paper that you are given which shows that you have paid for something','[ countable ]',null,'رسید، قبض؛ رسید (دریافت)؛ قبض (پول)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Keep your receipt in case you want to bring it back.","translation":"رسید خود را در صورتی که می خواهید آن را پس بگیرید نگه دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760074.mp3"},{"sentence":"Make sure you get receipts for everything.","translation":"مطمئن شوید که برای همه چیز رسید دریافت می کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604847.mp3"},{"sentence":"Can you give me a receipt?","translation":"آیا می توانید رسید به من بدهید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001876411.mp3"}]'::jsonb,3),
('df2d0417-7f75-5e0e-8798-868c65bb68b5','f7d9fdbb-3464-5eb3-915a-fe15d73ab1e1',2,null,null,'formal','when someone receives something','[ uncountable ]',null,'وقتی کسی چیزی را دریافت می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the closing date for receipt of applications","translation":"آخرین تاریخ برای دریافت درخواست ها","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760085.mp3"},{"sentence":"The booking will be made on receipt of a deposit.","translation":"رزرو با دریافت سپرده انجام می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760095.mp3"}]'::jsonb,2),
('28271738-5fec-5a24-ab71-730d41fc6206','f7d9fdbb-3464-5eb3-915a-fe15d73ab1e1',3,null,null,'spoken & written',null,null,'receipts','رسید، قبض؛ رسید (دریافت)؛ قبض (پول)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('2985e3b9-5c9c-567a-b5a7-9fc8285e02e2','ad46eff6-3365-5e3e-953f-b8e274c29132',1,'be given something','چیزی داده شود','spoken & written','to be given something',null,null,'دریافت کردن؛ رسیدگی کردن (درخواست)؛ مبتلا شدن (به)',array['get']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"All the children will receive a small gift.","translation":"همه بچه ها یک هدیه کوچک دریافت خواهند کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001770549.mp3"},{"sentence":"She received an honorary degree from Harvard.","translation":"او مدرک افتخاری را از هاروارد دریافت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001770552.mp3"},{"sentence":"She received no support from her parents.","translation":"او هیچ حمایتی از والدینش دریافت نکرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604855.mp3"},{"sentence":"They will be entitled to receive unemployment benefit.","translation":"آنها مستحق دریافت مقرری بیکاری خواهند بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604858.mp3"},{"sentence":"He went up to receive his award from the mayor.","translation":"او برای دریافت جایزه خود از شهردار بالا رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604861.mp3"},{"sentence":"16 to 18-year-olds receiving full-time education","translation":"افراد 16 تا 18 ساله که آموزش تمام وقت دارند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760117.mp3"},{"sentence":"Lee received 324 votes (= 324 people voted for him ) .","translation":"لی 324 رای دریافت کرد (= 324 نفر به او رای دادند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604874.mp3"},{"sentence":"What did you get for your birthday?","translation":"برای تولدت چی گرفتی؟","audio_url":null},{"sentence":"She got a degree from York University.","translation":"او از دانشگاه یورک مدرک گرفت.","audio_url":null}]'::jsonb,9),
('949b568a-7f9b-53e8-81c2-4999b0c4bf2b','ad46eff6-3365-5e3e-953f-b8e274c29132',2,'be sent something','چیزی فرستاده شود','formal','to get a letter , message , or telephone call, or something which someone has sent you',null,null,'برای دریافت نامه، پیام، یا تماس تلفنی، یا چیزی که شخصی برای شما ارسال کرده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He received a letter from his insurance company.","translation":"نامه ای از شرکت بیمه اش دریافت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604884.mp3"},{"sentence":"If you would like to receive further information , return the attached form.","translation":"اگر مایل به دریافت اطلاعات بیشتر هستید، فرم پیوست را برگردانید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604885.mp3"},{"sentence":"We have received numerous complaints about the noise.","translation":"ما شکایات متعددی در مورد سر و صدا دریافت کرده ایم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001876413.mp3"}]'::jsonb,3),
('1ae52ed3-01bf-5449-95cf-1425d9b29a32','ad46eff6-3365-5e3e-953f-b8e274c29132',3,'treatment','درمان','formal','if you receive a particular type of medical treatment , it is done to you',null,null,'اگر نوع خاصی از درمان پزشکی دریافت می کنید، برای شما انجام می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He received hospital treatment for a cut over his eye.","translation":"او به دلیل بریدگی چشمش تحت درمان بیمارستانی قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604891.mp3"}]'::jsonb,1),
('2d76398e-f7d3-5b50-a752-5f9757b5c919','ad46eff6-3365-5e3e-953f-b8e274c29132',4,'reaction to something','واکنش به چیزی','spoken & written','to react in a particular way to a suggestion , idea, performance etc',null,null,'به یک پیشنهاد، ایده، عملکرد و غیره واکنش خاصی نشان می دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The film was well received by critics (= they said it was good ) .","translation":"این فیلم مورد استقبال منتقدان قرار گرفت (= گفتند خوب است).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604895.mp3"},{"sentence":"He received the news in silence.","translation":"او این خبر را در سکوت دریافت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760148.mp3"}]'::jsonb,2),
('5f39a2b2-dca9-5dcf-8885-8b27bf3d8daf','ad46eff6-3365-5e3e-953f-b8e274c29132',5,null,null,'spoken & written',null,null,'be on/at the receiving end (of something)','دریافت کردن؛ رسیدگی کردن (درخواست)؛ مبتلا شدن (به)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('da81e43f-a51f-5a7e-9b35-877d9f367eab','ad46eff6-3365-5e3e-953f-b8e274c29132',6,null,null,'spoken & written',null,null,'receive an injury/blow','دریافت کردن؛ رسیدگی کردن (درخواست)؛ مبتلا شدن (به)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('0e7f8f49-5260-5b44-aaaf-d4a53aa193c7','ad46eff6-3365-5e3e-953f-b8e274c29132',7,'people','مردم','formal','to officially accept someone as a guest or member of a group',null,null,'پذیرفتن رسمی کسی به عنوان مهمان یا عضوی از یک گروه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She isn’t well enough to receive visitors yet.","translation":"او هنوز به اندازه کافی برای پذیرایی از بازدیدکنندگان خوب نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001604902.mp3"},{"sentence":"She was later received into the Church.","translation":"او بعداً در کلیسا پذیرفته شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760162.mp3"}]'::jsonb,2),
('57b55d59-827e-596b-804b-465523a2f913','ad46eff6-3365-5e3e-953f-b8e274c29132',8,'by radio','توسط رادیو','spoken & written','if a radio or television receives radio waves or other signals , it makes them become sounds or pictures',null,null,'اگر رادیو یا تلویزیون امواج رادیویی یا سیگنال های دیگر را دریافت کند، آنها را به صدا یا تصویر تبدیل می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Receiving you loud and clear!’","translation":"\"پذیرایی با صدای بلند و واضح!\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000760171.mp3"}]'::jsonb,1),
('fb6801f4-5da6-5758-89c0-af98619a44f0','f095739d-c8a6-5047-b5ef-7f7ec0d6dcd6',1,null,null,'spoken & written','to get better after an illness , accident , shock etc','[ intransitive ]',null,'بهبود یافتن، رهاسازی شدن (بیماری)؛ جبران کردن (ضرر)؛ بهبود (بازار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"After a few days of fever, she began to recover.","translation":"پس از چند روز تب، او شروع به بهبود کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614213.mp3"},{"sentence":"He’s in hospital, recovering from a heart attack.","translation":"او در بیمارستان بستری است و پس از سکته قلبی در حال نقاهت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001614216.mp3"},{"sentence":"I’ve recovered from my cold.","translation":"من از سرماخوردگی خلاص شدم","audio_url":null},{"sentence":"Don’t worry. You’ll soon get better .","translation":"نگران نباش به زودی بهتر میشی","audio_url":null}]'::jsonb,4),
