('cb222c9d-14a3-53e6-bd34-9a147c85b058','f095739d-c8a6-5047-b5ef-7f7ec0d6dcd6',5,null,null,'spoken & written','to get back an ability , a sense , or control over your feelings , movements etc after a period without it','[ transitive ]',null,'برای بازگرداندن یک توانایی، یک حس، یا کنترل بر احساسات، حرکات و غیره پس از یک دوره بدون آن',array['regain']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It was some hours before she recovered consciousness .","translation":"چند ساعت بود که به هوش آمد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000761748.mp3"},{"sentence":"Once she stumbled, but somehow she recovered her balance and carried on running.","translation":"یک بار تلو تلو خورد، اما به نوعی تعادل خود را به دست آورد و به دویدن ادامه داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001771433.mp3"},{"sentence":"He recovered himself enough to speak calmly.","translation":"آنقدر خودش را به دست آورد که آرام صحبت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001771441.mp3"}]'::jsonb,3),
