('23298c06-1476-5324-b72f-98daf3e0c78a','f860e2b5-51aa-5dae-89d2-d0acca15c2b8',4,'think about something','به چیزی فکر کن','spoken & written','to think carefully about something, or to say something that you have been thinking about','[ intransitive, transitive ]',null,'با دقت در مورد چیزی فکر کنید یا چیزی را بگویید که در مورد آن فکر می کردید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He had time to reflect on his successes and failures.","translation":"او زمان داشت تا در مورد موفقیت ها و شکست های خود فکر کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000768601.mp3"},{"sentence":"Moe reflected that he had never seen Sherry so happy.","translation":"مو فکر کرد که هرگز شری را تا این حد خوشحال ندیده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000768604.mp3"}]'::jsonb,2),
