('8dec55db-d02e-57b7-bf92-1a4f8ca025bc','bbdf2333-5857-5a60-8390-1b04dbba2722',1,null,null,'spoken & written','to find a satisfactory way of dealing with a problem or difficulty',null,null,'حل کردن؛ قطعیت پیدا کردن (عزم)؛ قطعیت (حالت)',array['solve']::text[],'{}'::text[],array['resolve a problem/crisis/situation Action is being taken to resolve the problem.','resolve a dispute/conflict Negotiation is the only way to resolve the dispute.','resolve an issue/matter/question Has the issue been resolved yet?','resolve your differences (= stop arguing with each other ) She and Rose had finally resolved their differences.','satisfactorily Some problems still hadn’t been satisfactorily resolved.','fully/completely It is a row that may never be fully resolved.','peacefully We wanted to resolve the situation peacefully.','amicably (= in a friendly way ) We will always do our best to resolve complaints amicably.','quickly The matter was resolved quite quickly.']::text[],'[{"sentence":"The crisis was resolved by negotiations.","translation":"بحران با مذاکره حل شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745226.mp3"},{"sentence":"Barnet was desperate for money to resolve his financial problems.","translation":"بارنت برای حل مشکلات مالی خود به دنبال پول بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745225.mp3"}]'::jsonb,2),
('fe9dcf04-0897-54be-b42f-0b6fc86485fb','bbdf2333-5857-5a60-8390-1b04dbba2722',2,null,null,'formal','to make a definite decision to do something',null,null,'تصمیم قطعی برای انجام کاری','{}'::text[],'{}'::text[],array['resolve a problem/crisis/situation Action is being taken to resolve the problem.','resolve a dispute/conflict Negotiation is the only way to resolve the dispute.','resolve an issue/matter/question Has the issue been resolved yet?','resolve your differences (= stop arguing with each other ) She and Rose had finally resolved their differences.','satisfactorily Some problems still hadn’t been satisfactorily resolved.','fully/completely It is a row that may never be fully resolved.','peacefully We wanted to resolve the situation peacefully.','amicably (= in a friendly way ) We will always do our best to resolve complaints amicably.','quickly The matter was resolved quite quickly.']::text[],'[{"sentence":"After the divorce she resolved never to marry again.","translation":"او پس از طلاق تصمیم گرفت که دیگر ازدواج نکند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745233.mp3"},{"sentence":"Mary resolved that she would stop smoking.","translation":"مریم تصمیم گرفت که سیگار را ترک کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745236.mp3"}]'::jsonb,2),
('7060b427-7f89-5147-ab33-b344f601ec74','bbdf2333-5857-5a60-8390-1b04dbba2722',3,null,null,'spoken & written','to make a formal decision, especially by voting',null,null,'تصمیم گیری رسمی، به ویژه با رای دادن','{}'::text[],'{}'::text[],array['resolve a problem/crisis/situation Action is being taken to resolve the problem.','resolve a dispute/conflict Negotiation is the only way to resolve the dispute.','resolve an issue/matter/question Has the issue been resolved yet?','resolve your differences (= stop arguing with each other ) She and Rose had finally resolved their differences.','satisfactorily Some problems still hadn’t been satisfactorily resolved.','fully/completely It is a row that may never be fully resolved.','peacefully We wanted to resolve the situation peacefully.','amicably (= in a friendly way ) We will always do our best to resolve complaints amicably.','quickly The matter was resolved quite quickly.']::text[],'[{"sentence":"The Senate resolved to accept the president’s proposals.","translation":"سنا تصمیم گرفت پیشنهادات رئیس جمهور را بپذیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745244.mp3"}]'::jsonb,1),
('b3dee77f-82dc-5e6b-8594-cf4c57d18b18','bbdf2333-5857-5a60-8390-1b04dbba2722',4,null,null,'technical','to separate something into its different parts',null,null,'برای جدا کردن چیزی به قسمت های مختلف آن','{}'::text[],'{}'::text[],array['resolve a problem/crisis/situation Action is being taken to resolve the problem.','resolve a dispute/conflict Negotiation is the only way to resolve the dispute.','resolve an issue/matter/question Has the issue been resolved yet?','resolve your differences (= stop arguing with each other ) She and Rose had finally resolved their differences.','satisfactorily Some problems still hadn’t been satisfactorily resolved.','fully/completely It is a row that may never be fully resolved.','peacefully We wanted to resolve the situation peacefully.','amicably (= in a friendly way ) We will always do our best to resolve complaints amicably.','quickly The matter was resolved quite quickly.']::text[],'[{"sentence":"DNA samples were extracted and resolved.","translation":"نمونه DNA استخراج و حل شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626056.mp3"}]'::jsonb,1),
('4dbd8479-8e97-534f-9a88-4bbeda64e316','e762215e-ce78-5f45-8cef-559db594921d',1,null,null,'formal','strong determination to succeed in doing something',null,null,'عزم قوی برای موفقیت در انجام کاری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Recent events strengthened her resolve to find out the truth.","translation":"وقایع اخیر عزم او را برای کشف حقیقت تقویت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745280.mp3"}]'::jsonb,1),
('f88bd616-01a1-56e9-b72b-331dc79314bf','c081d7ac-90da-51b3-b73b-dcf37fb7b1ef',1,'admiration','تحسین','spoken & written','a feeling of admiring someone or what they do, especially because of their personal qualities , knowledge , or skills','[ uncountable ]',null,'احترام، احترام‌گذاری؛ رعایت (قوانین)؛ عزّت','{}'::text[],'{}'::text[],array['have respect for somebody I have a lot of respect for my boss.','win/earn/gain respect (= start to be respected ) Morris eventually won the respect of his fellow workers.','command respect (= be respected ) Lady Thatcher commanded huge respect from everyone she worked with.','deserve respect Nurses deserve our respect and admiration.','lose respect for somebody (= no longer respect them ) She had lost all respect for him.','lose somebody’s respect (= no longer be respected by them ) Once a child knows you have lied, you will lose their respect.','great respect Rex and Joe had great respect for his judgement.','the utmost respect I have the utmost respect for the prime minister.','mutual respect (= when two people respect each other ) Their relationship is based on mutual respect.','grudging respect (= when you respect someone or something unwillingly ) Initially his idea was seen as far-fetched, but gradually it has received grudging respect and support.']::text[],'[{"sentence":"I have the greatest respect for Jane’s work.","translation":"من برای کار جین بیشترین احترام را قائلم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745577.mp3"}]'::jsonb,1),
('54ef6eca-94d1-5e30-8da2-f6988b71f4d5','c081d7ac-90da-51b3-b73b-dcf37fb7b1ef',2,'consideration','در نظر گرفتن','spoken & written','the belief that something or someone is important and should not be harmed , treated rudely etc','[ uncountable ]',null,'اعتقاد به اینکه چیزی یا کسی مهم است و نباید به او صدمه ای وارد شود، با بی ادبی رفتار شود و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Out of respect for the wishes of her family, the affair was not reported in the media.","translation":"به دلیل احترام به خواسته های خانواده او، این ماجرا در رسانه ها منتشر نشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745602.mp3"},{"sentence":"The boys showed a complete lack of respect for authority.","translation":"پسرها کاملاً به اقتدار احترام نمی گذارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745603.mp3"},{"sentence":"Your mother should be treated with respect.","translation":"با مادرت باید با احترام رفتار کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001339.mp3"}]'::jsonb,3),
('beea08bf-ec9e-562f-8af8-43af26e455b9','c081d7ac-90da-51b3-b73b-dcf37fb7b1ef',3,null,null,'spoken & written',null,null,'with (the greatest) respect/with (all) due respect','احترام، احترام‌گذاری؛ رعایت (قوانین)؛ عزّت','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('e66994dd-7762-50a6-96e3-9b1a860cbfc7','c081d7ac-90da-51b3-b73b-dcf37fb7b1ef',4,'for danger','برای خطر','spoken & written','a careful attitude towards something or someone that could be dangerous','[ singular, uncountable ]',null,'نگرش دقیق نسبت به چیزی یا شخصی که می تواند خطرناک باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My fear turned into a respect for the sea.","translation":"ترس من تبدیل به احترام به دریا شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626119.mp3"},{"sentence":"People should have a healthy respect for alcohol (= a sensible careful attitude towards it ) .","translation":"مردم باید به الکل احترام بگذارند (= نگرش دقیق و معقول نسبت به آن).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745614.mp3"}]'::jsonb,2),
