('98ba61df-decb-5781-8d0b-3a09d6702592','06964d0d-f592-54b3-b39c-0bb8d64d7ad6',1,null,null,'spoken & written','to admire someone because they have high standards and good qualities such as fairness and honesty','[ not in progressive ]',null,'کسی را تحسین کنید زیرا استانداردهای بالایی دارد و ویژگی های خوبی مانند انصاف و صداقت دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She respected him for his honesty.","translation":"به خاطر صداقتش به او احترام می گذاشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745675.mp3"},{"sentence":"I respect his views, although I do not agree with them.","translation":"من به نظرات او احترام می گذارم، اگرچه با آنها موافق نیستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001773317.mp3"}]'::jsonb,2),
('0109cb24-947b-5e61-ae01-6826e483ad16','06964d0d-f592-54b3-b39c-0bb8d64d7ad6',2,null,null,'spoken & written','to be careful not to do anything against someone’s wishes, rights etc',null,null,'مراقب باشید کاری بر خلاف میل، حقوق و غیره کسی انجام ندهید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She said she wanted to leave, and her father respected her wishes .","translation":"او گفت که می خواهد برود و پدرش به خواسته های او احترام گذاشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745679.mp3"},{"sentence":"I would like you to respect my privacy.","translation":"از شما می خواهم به حریم خصوصی من احترام بگذارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001773318.mp3"},{"sentence":"the need to respect human rights","translation":"لزوم رعایت حقوق بشر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001876890.mp3"}]'::jsonb,3),
('a79457e0-6852-51be-88e6-6649909dbba9','06964d0d-f592-54b3-b39c-0bb8d64d7ad6',3,null,null,'spoken & written','to not break a rule or law',null,null,'برای اینکه قانون یا قانون را زیر پا نگذاریم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The president is expected to respect the constitution.","translation":"انتظار می رود رئیس جمهور به قانون اساسی احترام بگذارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001773326.mp3"}]'::jsonb,1),
('9b8ce3bf-4d28-5e94-8273-51a0437cc4fa','e4c86908-092b-5194-858b-dbe0ae8ad8ed',1,null,null,'spoken & written','a left-wing political party in England and Wales which was started in January 2004. Its name is made up of the first letters of the words Respect, Equality , Socialism , Peace , Environmentalism, and Trade Unionism . Its supporters include the film director Ken Loach and the playwright Harold Pinter. One of the party’s most important members is George Galloway. The party’s full name is Respect – The Unity Coalition .',null,null,'یک حزب سیاسی جناح چپ در انگلستان و ولز که در ژانویه 2004 تأسیس شد. نام آن از حروف اول کلمات Respect، Equality، Socialism، Peace، Environmentalism و Trade Unionism تشکیل شده است. حامیان آن عبارتند از کن لوچ کارگردان فیلم و هارولد پینتر نمایشنامه نویس. یکی از مهم ترین اعضای حزب جورج گالووی است. نام کامل این حزب Respect – The Unity Coalition است.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('aad41a17-5311-513f-ba28-a2205a234afa','f2f4a4d4-d3cd-5413-8399-74b2ee23bf0e',1,null,null,'spoken & written','to do something as a reaction to something that has been said or done','[ intransitive ]',null,'پاسخ دادن؛ واکنش نشان دادن (به)؛ پاسخ‌گو بودن (پاسخ)',array['react']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Responding to the news, Mr Watt appealed for calm.","translation":"در پاسخ به این خبر، آقای وات خواستار آرامش شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745878.mp3"},{"sentence":"The US responded by sending troops into Laos.","translation":"ایالات متحده با اعزام نیرو به لائوس پاسخ داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745881.mp3"},{"sentence":"Villagers responded with offers of help.","translation":"روستاییان با پیشنهاد کمک پاسخ دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001773335.mp3"}]'::jsonb,3),
('c4e2dff4-b368-569e-81ca-8beab15283d3','f2f4a4d4-d3cd-5413-8399-74b2ee23bf0e',2,null,null,'spoken & written','to say or write something as a reply','[ intransitive, transitive ]',null,'گفتن یا نوشتن چیزی به عنوان پاسخ','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He responded that he didn’t want to see anyone.","translation":"او پاسخ داد که نمی خواهد کسی را ببیند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745892.mp3"},{"sentence":"Dave didn’t respond to any of her emails.","translation":"دیو به هیچ یک از ایمیل های او پاسخ نداد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626170.mp3"}]'::jsonb,2),
('16ef1a34-a2f6-54a3-b041-392e15117b83','f2f4a4d4-d3cd-5413-8399-74b2ee23bf0e',3,null,null,'spoken & written','to improve as a result of a particular kind of treatment','[ intransitive ]',null,'برای بهبود در نتیجه نوع خاصی از درمان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She has responded well to treatment.","translation":"او به خوبی به درمان پاسخ داده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745902.mp3"},{"sentence":"Colds do not respond to antibiotics.","translation":"سرماخوردگی به آنتی بیوتیک ها پاسخ نمی دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745903.mp3"}]'::jsonb,2),
('b5357ba2-b530-5f74-999b-56512931d791','bcbfe353-ece1-5584-a137-5d6558740e5e',1,'former situation','وضعیت سابق','spoken & written','to make something return to its former state or condition',null,null,'بازگرداندن، بازگردانی کردن (حالت)؛ مرمت کردن (اثر)؛ احیاء کردن (نظم)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The government promises to restore the economy to full strength.","translation":"دولت وعده می دهد اقتصاد را به قدرت کامل بازگرداند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746606.mp3"},{"sentence":"She was hoping that the Mediterranean climate would restore her to full health.","translation":"او امیدوار بود که آب و هوای مدیترانه ای او را به سلامت کامل بازگرداند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562946.mp3"},{"sentence":"The National Guard was called in to restore order (= make people stop fighting and breaking the law ) when riots broke out.","translation":"گارد ملی برای بازگرداندن نظم (= وادار کردن مردم از جنگیدن و نقض قانون) فراخوانده شد که شورش ها شروع شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562955.mp3"},{"sentence":"initiatives to restore peace in the Middle East","translation":"ابتکار عمل برای بازگرداندن صلح در خاورمیانه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562956.mp3"},{"sentence":"Vietnam restored diplomatic relations with South Korea on December 22.","translation":"ویتنام در 22 دسامبر روابط دیپلماتیک خود را با کره جنوبی احیا کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562962.mp3"}]'::jsonb,5),
('f8939ca4-5baa-504e-b031-012429076700','bcbfe353-ece1-5584-a137-5d6558740e5e',2,'positive feeling','احساس مثبت','spoken & written','to bring back a positive feeling that a person or a group of people felt before',null,null,'برای بازگرداندن احساس مثبتی که یک فرد یا گروهی از مردم قبلاً احساس می کردند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"measures aimed at restoring public confidence in the education system","translation":"اقداماتی با هدف بازگرداندن اعتماد عمومی به نظام آموزشی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746611.mp3"},{"sentence":"a man whose kindness and sincerity really restored my faith in human nature (= helped me to believe that people can be good )","translation":"مردی که مهربانی و صداقتش واقعا ایمانم را به طبیعت انسانی بازگرداند (= به من کمک کرد باور کنم که مردم می توانند خوب باشند)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562970.mp3"}]'::jsonb,2),
('f093330a-4f13-5da2-9152-0fc20f53d1b7','bcbfe353-ece1-5584-a137-5d6558740e5e',3,'repair','تعمیر','spoken & written','to repair an old building, piece of furniture , or painting etc so that it is in its original condition',null,null,'برای تعمیر یک ساختمان قدیمی، یک قطعه مبلمان، یا نقاشی و غیره به طوری که در شرایط اولیه خود باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The church was carefully restored after the war.","translation":"کلیسا پس از جنگ با دقت بازسازی شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000746622.mp3"},{"sentence":"a Victorian fireplace restored to its former glory","translation":"یک شومینه ویکتوریایی که به شکوه سابق خود بازیابی شد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001562974.mp3"}]'::jsonb,2),
