('918b8e31-e71f-5ae9-8cb1-51152de6bc73','2704a48c-b59e-5c76-b7c6-99827dfa0885',1,null,null,'spoken & written','not skilful at a particular activity',null,null,'در یک فعالیت خاص ماهر نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a rubbish team","translation":"یک تیم زباله","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000733174.mp3"}]'::jsonb,1),
('e69acba8-0ff9-51f5-8640-530683b1cbb0','922f2593-a3c0-52af-ba49-941a8ed108f1',1,null,null,'spoken & written','to make someone feel pleased by doing what they want',null,null,'خشنود کردن، راضی کردن؛ برآوردن (نیاز)؛ جواب دادن (شرایط)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Nothing I did would ever satisfy my father.","translation":"هیچ کاری که انجام دادم پدرم را راضی نمی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000714565.mp3"}]'::jsonb,1),
('4e9e012f-f182-59ea-8cb7-139b2b729a19','922f2593-a3c0-52af-ba49-941a8ed108f1',2,null,null,'spoken & written','if you satisfy someone’s needs, demands etc, you provide what they need or want',null,null,'اگر نیازها، خواسته‌ها و غیره کسی را برآورده کنید، آنچه را که نیاز دارد یا می‌خواهد فراهم می‌کنید','{}'::text[],'{}'::text[],array['satisfy a need Education must satisfy the needs of its pupils.','satisfy a demand The company was unable to satisfy demand for the product.','satisfy somebody''s appetite/hunger They don''t get enough food to satisfy their appetite.','satisfy a desire It is difficult to satisfy a desire for power.','satisfy an urge Her urge to travel had never been satisfied.','satisfy somebody''s curiosity (= let someone know something they want to know ) I had to read the letter, just to satisfy my curiosity.','satisfy somebody''s wants (= provide the things that someone wants ) We work hard to satisfy customers'' wants.','satisfy somebody''s aspirations (= provide the things that someone hopes to get ) The new government failed to satisfy the aspirations of the people.','satisfy somebody''s cravings (= satisfy a strong desire ) I needed to satisfy my cravings for chocolate.']::text[],'[{"sentence":"The program is designed to satisfy the needs of adult learners.","translation":"این برنامه برای برآوردن نیازهای زبان آموزان بزرگسال طراحی شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001634119.mp3"},{"sentence":"A salad won’t be enough to satisfy my appetite.","translation":"یک سالاد برای رفع اشتهای من کافی نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001634123.mp3"},{"sentence":"Just to satisfy my curiosity (= find out something ) , how much did it cost?","translation":"فقط برای ارضای کنجکاوی من (= چیزی را پیدا کنم)، هزینه آن چقدر شد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001634128.mp3"}]'::jsonb,3),
('c24800a7-341e-51ec-8f3c-f2b7964e5cbc','922f2593-a3c0-52af-ba49-941a8ed108f1',3,null,null,'formal','to make someone feel sure that something is right or true',null,null,'برای اینکه کسی احساس کند چیزی درست یا درست است',array['convince']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Jackson tried to satisfy me of his innocence.","translation":"جکسون سعی کرد من را از بی گناهی اش راضی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000714582.mp3"},{"sentence":"Having satisfied herself that no one was there, she closed the door.","translation":"او که راضی بود کسی آنجا نیست، در را بست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001634131.mp3"}]'::jsonb,2),
