('0a80ff00-3f21-5e9f-93ab-8b36edd5f77e','084720d7-f461-50b2-8b5a-a1df444bb17f',2,'cut somebody’s skin','پوست کسی را بریدن','spoken & written','to cut someone’s skin slightly with your nails or with something sharp','[ intransitive, transitive ]',null,'پوست کسی را کمی با ناخن یا چیزی تیز بریدن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She ran at him and scratched his face.","translation":"به طرفش دوید و صورتش را خاراند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001610981.mp3"},{"sentence":"Don’t scratch yourself on the thorns.","translation":"خود را روی خارها نخراشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001610982.mp3"}]'::jsonb,2),
