('bfddd6a7-e1c9-5054-a358-c682ed8870f4','084720d7-f461-50b2-8b5a-a1df444bb17f',4,'animals','حیوانات','spoken & written','if an animal scratches, it rubs its feet against something, often making a noise','[ intransitive always + adverb/preposition ]',null,'اگر حیوانی خراش می‌دهد، پاهایش را به چیزی می‌مالد و اغلب صدا ایجاد می‌کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A few chickens scratched around in the yard.","translation":"چند جوجه در حیاط خراشیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001610985.mp3"},{"sentence":"a dog scratching at the door to be let in","translation":"سگی که در را می خراشد تا اجازه ورود پیدا کند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000721491.mp3"}]'::jsonb,2),
('d945a280-1603-5d54-ab7d-20298eef5a10','084720d7-f461-50b2-8b5a-a1df444bb17f',5,'remove something','چیزی را حذف کنید','spoken & written','to remove something from a surface by rubbing it with something sharp','[ transitive always + adverb/preposition ]',null,'برداشتن چیزی از روی سطح با مالیدن آن با چیزی تیز','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I scratched away a little of the paint with my fingernail.","translation":"با ناخنم کمی از رنگ را خراش دادم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000721499.mp3"}]'::jsonb,1),
