('316a2420-945c-5e26-9254-b8418f1dac3b','f0779c34-e561-56a4-9335-c7fcb64bcf2d',4,null,null,'spoken & written','used when saying that two things are clearly and noticeably very different',null,null,'وقتی می گوییم دو چیز به وضوح و به طور قابل توجهی بسیار متفاوت هستند استفاده می شود','{}'::text[],'{}'::text[],array['rise/increase sharply The value of early photographs has risen sharply in recent years.','fall/drop sharply Oil prices fell sharply.','sharply reduce/cut something These measures could sharply reduce pollution from road traffic.']::text[],'[{"sentence":"Opinion is sharply divided .","translation":"نظرات به شدت تقسیم شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000711241.mp3"},{"sentence":"His beliefs and values contrast sharply with (= are very different from ) his father’s.","translation":"باورها و ارزش های او به شدت با (= بسیار متفاوت از) پدرش است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001637175.mp3"}]'::jsonb,2),
('36d57809-ea46-5724-a30e-bde048e4134b','048357d4-1a14-57b3-98b0-5a05fc85b020',1,null,null,'spoken & written','a place to live, considered as one of the basic needs of life','[ uncountable ]',null,'پناهگاه، سرپناه؛ پناه (گاه)؛ پناه (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They are in need of food and shelter.","translation":"آنها به غذا و سرپناه نیاز دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000712517.mp3"}]'::jsonb,1),
('37328f0a-c9dc-5c41-b1ba-0a3a77106ffb','048357d4-1a14-57b3-98b0-5a05fc85b020',2,null,null,'spoken & written','protection from danger or from wind , rain , hot sun etc','[ uncountable ]',null,'محافظت در برابر خطر یا باد، باران، آفتاب داغ و غیره','{}'::text[],'{}'::text[],array['take shelter (= go into a place where you are protected from something ) When it started raining, they took shelter in a cave.','find shelter He slept wherever he could find shelter.','seek shelter formal (= try to find shelter ) They sought shelter under the trees.','run for shelter The residents were running for shelter from the bombing.','give/provide shelter The trees gave shelter from the wind.']::text[],'[{"sentence":"We reached the shelter of the caves.","translation":"به پناهگاه غارها رسیدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588362.mp3"},{"sentence":"They were standing under the shelter of a huge tree.","translation":"زیر پناه درختی عظیم ایستاده بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588363.mp3"},{"sentence":"The men took shelter in a bombed-out farmhouse.","translation":"مردان در یک خانه مزرعه بمباران شده پناه گرفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000712528.mp3"},{"sentence":"All around me, people were running for shelter .","translation":"در اطراف من، مردم برای سرپناه می دویدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000712531.mp3"},{"sentence":"An old hut gave shelter from the storm.","translation":"یک کلبه قدیمی از طوفان پناه گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588372.mp3"}]'::jsonb,5),
('d7c9edad-3bf4-56d4-bba1-eecc95b7e261','048357d4-1a14-57b3-98b0-5a05fc85b020',3,null,null,'spoken & written','a building where people or animals that have nowhere to live or that are in danger can stay and receive help','[ countable ]',null,'ساختمانی که در آن افراد یا حیواناتی که جایی برای زندگی ندارند یا در معرض خطر هستند می توانند در آن بمانند و کمک دریافت کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a shelter for battered women","translation":"پناهگاهی برای زنان کتک خورده","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588382.mp3"},{"sentence":"a homeless shelter (= for people who have no homes )","translation":"سرپناه بی خانمان (= برای افرادی که خانه ندارند)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588383.mp3"},{"sentence":"an animal shelter","translation":"یک پناهگاه حیوانات","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588387.mp3"}]'::jsonb,3),
('87302e16-afe0-50b8-9ae0-d91454d366e9','048357d4-1a14-57b3-98b0-5a05fc85b020',4,null,null,'spoken & written','a building or an area with a roof over it that protects you from the weather or from danger','[ countable ]',null,'ساختمان یا منطقه ای با سقفی که از شما در برابر آب و هوا یا خطر محافظت می کند','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('af809d61-cd27-54e4-acf4-bd7d218dcb99','483b2bcb-2ed1-53a2-9594-85103e0cfe9c',1,null,null,'spoken & written','to provide a place where someone or something is protected, especially from the weather or from danger','[ transitive ]',null,'فراهم کردن مکانی که در آن شخص یا چیزی محافظت شود، به ویژه در برابر آب و هوا یا خطر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Collins was arrested for sheltering enemy soldiers.","translation":"کالینز به دلیل پناه دادن به سربازان دشمن دستگیر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000712560.mp3"},{"sentence":"Plant herbs next to a wall to shelter them from the wind.","translation":"گیاهان را در کنار دیوار بکارید تا از باد در امان بمانید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000712563.mp3"}]'::jsonb,2),
('9cf8c740-b173-5eda-9020-c27a4740572e','483b2bcb-2ed1-53a2-9594-85103e0cfe9c',2,null,null,'spoken & written','to stay in or under a place where you are protected from the weather or from danger','[ intransitive ]',null,'برای ماندن در یا زیر مکانی که از آب و هوا یا خطر محافظت می کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We sat in the shade, sheltering from the sun.","translation":"زیر سایه نشستیم و از آفتاب در امان بودیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000712570.mp3"}]'::jsonb,1),
('c58cc7f4-dddc-5b13-8b66-bcbb93923f69','ffd60305-072e-5add-9e83-9be0080d6721',1,null,null,'spoken & written','a British charity organization that helps people who are homeless (= do not have a home to live in )',null,null,'یک سازمان خیریه بریتانیایی که به افرادی که بی خانمان هستند (= خانه ای برای زندگی ندارند) کمک می کند.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('7f32e2be-ab2b-5503-b33b-d97d34c24dd5','47dcf55f-6e89-54b3-824d-67f23b07406d',1,null,null,'spoken & written','feeling surprised and upset by something very unexpected and unpleasant',null,null,'مبهوت، شوکه؛ دلسرد (از)','{}'::text[],'{}'::text[],array['deeply/very/really shocked We are all deeply shocked by what’s happened.','quite shocked I was quite shocked by her appearance.','genuinely shocked Gilbert sounded genuinely shocked.','visibly shocked Yesterday she was visibly shocked by the conditions she witnessed in the camps.','shocked silence There was a moment of shocked silence.','shocked surprise He smiled at Donna’s expression of shocked surprise.','seem/look/appear shocked He glanced at his mother, who looked shocked.','sound shocked "Of course not!" he exclaimed, sounding shocked.']::text[],'[{"sentence":"I was deeply shocked by Jo’s death.","translation":"من عمیقاً از مرگ جو شوکه شدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588991.mp3"},{"sentence":"He is shocked at what happened to his son.","translation":"او از اتفاقی که برای پسرش افتاده شوکه شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000675812.mp3"},{"sentence":"She gave him a shocked look.","translation":"نگاهی مبهوت به او انداخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588998.mp3"},{"sentence":"For a few minutes she stood in shocked silence .","translation":"چند دقیقه ای در سکوت شوکه شده ایستاد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000675820.mp3"},{"sentence":"We were too shocked to talk.","translation":"ما آنقدر شوکه شده بودیم که نمی توانستیم صحبت کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001588995.mp3"}]'::jsonb,5),
('672fb926-b159-52d1-b1ea-430a20543522','47dcf55f-6e89-54b3-824d-67f23b07406d',2,null,null,'spoken & written','very offended because something seems immoral or socially unacceptable',null,null,'به دلیل اینکه چیزی غیراخلاقی یا از نظر اجتماعی غیرقابل قبول به نظر می رسد بسیار توهین شده است','{}'::text[],'{}'::text[],array['deeply/very/really shocked We are all deeply shocked by what’s happened.','quite shocked I was quite shocked by her appearance.','genuinely shocked Gilbert sounded genuinely shocked.','visibly shocked Yesterday she was visibly shocked by the conditions she witnessed in the camps.','shocked silence There was a moment of shocked silence.','shocked surprise He smiled at Donna’s expression of shocked surprise.','seem/look/appear shocked He glanced at his mother, who looked shocked.','sound shocked "Of course not!" he exclaimed, sounding shocked.']::text[],'[{"sentence":"Many people were shocked by the film when it first came out.","translation":"بسیاری از مردم در اولین اکران از این فیلم شوکه شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001980611.mp3"},{"sentence":"They were deeply shocked at her behaviour.","translation":"آنها به شدت از رفتار او شوکه شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001980614.mp3"}]'::jsonb,2),
('7c188822-b422-5172-a106-6223f4c7a25b','6bcca65f-f32a-5fa3-9775-29c159f41e81',1,null,null,'spoken & written','soon',null,null,'بزودی، به‌زودی؛ به‌طور نزدیک','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Ms Jones will be back shortly.","translation":"خانم جونز به زودی برمی گردد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000677672.mp3"},{"sentence":"The accident happened shortly before midday.","translation":"این حادثه کمی قبل از ظهر رخ داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001775857.mp3"}]'::jsonb,2),
('3376deb4-b62e-5c5f-be59-aa88e4edaf3d','6bcca65f-f32a-5fa3-9775-29c159f41e81',2,null,null,'written','speaking in an impatient and unfriendly way',null,null,'به شیوه ای بی حوصله و غیر دوستانه صحبت می کند',array['abruptly']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘I’ve explained that already, ’ Rod said shortly.","translation":"راد کوتاه گفت: \"من قبلاً توضیح داده ام.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000677679.mp3"}]'::jsonb,1),
('eca89cc2-55ca-57c3-ba26-914361f29575','c45a1513-3d83-5880-b786-7f00360ac1d3',1,'no noise','بدون سر و صدا','spoken & written','complete absence of sound or noise','[ uncountable ]',null,'سکوت، سکوت (نسبی)؛ سکوت (حس)؛ بی‌صدا (مکان)',array['quiet']::text[],'{}'::text[],array['complete/total/absolute/utter silence They sat in complete silence. The silence in the room was absolute.','dead silence (= complete silence ) There was a gasp from Peter and then a dead silence.','a long silence ‘He’s dead.’ There was a long silence.','a short/brief silence After a brief silence, Katherine nodded.','an awkward/uncomfortable/embarrassed silence ‘Fred tells me you like books, ’ Steve said, after an awkward silence.','a stunned/shocked silence There was a stunned silence at the other end of the phone.','stony silence (= unfriendly silence ) Harrison stared at him in stony silence.','a tense silence There was a brief, tense silence.','an eerie silence (= one that is strange and rather frightening ) An eerie silence descended over the house.','an ominous silence (= one that makes you feel that something bad is going to happen ) ‘How long will she be ill?’ There was a short, ominous silence.','a sudden silence At the mention of John, a sudden silence fell on the room.','there is (a) silence There was silence in the library for several moments.','break/shatter the silence (= end the silence ) The sound of a car engine broke the silence.','disturb the silence (= end the silence by making a sound ) Nothing moved, no sound disturbed the silence.','silence falls/descends (= a silence begins ) A sudden silence fell over the room.','lapse into silence (= to stop talking and be quiet ) ''I don''t want any, '' he said, and lapsed into silence again.']::text[],'[{"sentence":"Nothing disturbed the silence of the night.","translation":"هیچ چیز سکوت شب را بر هم نمی زد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685696.mp3"},{"sentence":"After the explosion, an eerie silence fell upon the scene.","translation":"پس از انفجار، سکوت وحشتناکی بر صحنه حاکم شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685700.mp3"},{"sentence":"A loud scream shattered the silence.","translation":"صدای جیغ بلندی سکوت را در هم شکست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685703.mp3"}]'::jsonb,3),
('47453656-bf5d-593e-8d7f-eb6540b59af7','c45a1513-3d83-5880-b786-7f00360ac1d3',2,'no talking','بدون صحبت','spoken & written','complete quiet because nobody is talking','[ countable, uncountable ]',null,'کاملا ساکته چون کسی حرف نمیزنه','{}'::text[],'{}'::text[],array['complete/total/absolute/utter silence They sat in complete silence. The silence in the room was absolute.','dead silence (= complete silence ) There was a gasp from Peter and then a dead silence.','a long silence ‘He’s dead.’ There was a long silence.','a short/brief silence After a brief silence, Katherine nodded.','an awkward/uncomfortable/embarrassed silence ‘Fred tells me you like books, ’ Steve said, after an awkward silence.','a stunned/shocked silence There was a stunned silence at the other end of the phone.','stony silence (= unfriendly silence ) Harrison stared at him in stony silence.','a tense silence There was a brief, tense silence.','an eerie silence (= one that is strange and rather frightening ) An eerie silence descended over the house.','an ominous silence (= one that makes you feel that something bad is going to happen ) ‘How long will she be ill?’ There was a short, ominous silence.','a sudden silence At the mention of John, a sudden silence fell on the room.','there is (a) silence There was silence in the library for several moments.','break/shatter the silence (= end the silence ) The sound of a car engine broke the silence.','disturb the silence (= end the silence by making a sound ) Nothing moved, no sound disturbed the silence.','silence falls/descends (= a silence begins ) A sudden silence fell over the room.','lapse into silence (= to stop talking and be quiet ) ''I don''t want any, '' he said, and lapsed into silence again.']::text[],'[{"sentence":"There was a brief silence before anyone answered.","translation":"قبل از اینکه کسی جواب بدهد سکوت کوتاهی برقرار شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685712.mp3"},{"sentence":"The four men sat in silence.","translation":"چهار مرد در سکوت نشستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001775231.mp3"},{"sentence":"‘How long have you been here?’ I asked. There was complete silence.","translation":"پرسیدم: \"چند وقت است که اینجا هستید؟\" سکوت کامل حاکم شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001775232.mp3"},{"sentence":"‘Silence in court!’ roared the judge.","translation":"قاضی فریاد زد: «سکوت در دادگاه!»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672817.mp3"},{"sentence":"There was an awkward silence between them.","translation":"سکوت عجیبی بین آنها حاکم شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672818.mp3"},{"sentence":"The accused exercised his right to silence (= the legal right to choose to say nothing ) .","translation":"متهم از حق خود برای سکوت (=حق قانونی انتخاب چیزی نگفتن) استفاده کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672822.mp3"}]'::jsonb,6),
('95e84ab0-ee69-57c2-b720-f96e969abdfe','c45a1513-3d83-5880-b786-7f00360ac1d3',3,'no discussion/answer','بدون بحث/پاسخ','spoken & written','failure or refusal to discuss something or answer questions about something','[ uncountable ]',null,'شکست یا امتناع از بحث در مورد چیزی یا پاسخ به سؤالات در مورد چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The government’s silence on such an important issue seems very strange.","translation":"سکوت دولت در قبال چنین موضوع مهمی بسیار عجیب به نظر می رسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685732.mp3"},{"sentence":"Once again the answer was a deafening silence (= a very noticeable refusal to discuss something ) .","translation":"یک بار دیگر پاسخ یک سکوت کر کننده بود (= امتناع بسیار محسوس از بحث در مورد چیزی).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672826.mp3"}]'::jsonb,2),
('37de2461-cc80-56b4-b17c-a650cbc121ad','c45a1513-3d83-5880-b786-7f00360ac1d3',4,'no communication','بدون ارتباط','spoken & written','failure to write a letter to someone, telephone them etc','[ uncountable ]',null,'عدم نوشتن نامه به کسی، تماس تلفنی و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"After two years of silence, he suddenly got in touch with us again.","translation":"بعد از دو سال سکوت ناگهان دوباره با ما تماس گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685742.mp3"}]'::jsonb,1),
('33d57b39-bcc5-5c10-bce6-b69e132c0063','c45a1513-3d83-5880-b786-7f00360ac1d3',5,null,null,'spoken & written',null,null,'one-minute/two-minute etc silence','سکوت، سکوت (نسبی)؛ سکوت (حس)؛ بی‌صدا (مکان)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ce038986-6b9e-5050-b493-26f045528614','235c93c9-36c2-5a4e-af59-2c6e6c96cad9',1,null,null,'spoken & written','to make someone stop talking, or stop something making a noise',null,null,'وادار کردن کسی از صحبت کردن، یا متوقف کردن چیزی که سر و صدا می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She held up her hand to silence the children.","translation":"دستش را بالا گرفت تا بچه ها را ساکت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685761.mp3"}]'::jsonb,1),
('13fa076c-9f4b-5d9e-9459-1b519f008c5a','235c93c9-36c2-5a4e-af59-2c6e6c96cad9',2,null,null,'spoken & written','to make someone stop expressing opposition or criticisms – used especially in news reports',null,null,'وادار کردن کسی از ابراز مخالفت یا انتقاد - به ویژه در گزارش های خبری استفاده شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"attempts to silence the rumours","translation":"تلاش برای خاموش کردن شایعات","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685765.mp3"},{"sentence":"Barnes has failed to silence his critics.","translation":"بارنز نتوانسته است منتقدانش را ساکت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000685766.mp3"}]'::jsonb,2),
('fdf16fb6-ac28-542d-a28f-cab8ab99d3cc','ffbb2338-66db-59c0-9545-6b42d3b73d3d',1,null,null,'spoken & written','almost the same',null,null,'مشابه، مشابه (چیز)؛ مشابه (فرد)','{}'::text[],'{}'::text[],array['very similar I was in a very similar situation not so long ago.','broadly/roughly similar The new employment terms and conditions will be broadly similar to those currently in place.','remarkably/strikingly/startlingly similar The results of each study are remarkably similar.','quite/fairly similar The two species are quite similar.','somewhat similar Their reactions were somewhat similar.']::text[],'[{"sentence":"We have similar tastes in music.","translation":"ما در موسیقی سلیقه های مشابهی داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000582594.mp3"},{"sentence":"Both approaches seem to achieve similar results.","translation":"به نظر می رسد هر دو رویکرد به نتایج مشابهی دست می یابند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001585149.mp3"},{"sentence":"A number of his friends had been affected in a similar way .","translation":"تعدادی از دوستان او نیز به روشی مشابه تحت تأثیر قرار گرفته بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001585150.mp3"},{"sentence":"The two products look quite similar .","translation":"این دو محصول کاملا شبیه به هم هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001585154.mp3"},{"sentence":"Her ideas are quite similar to mine.","translation":"ایده های او کاملاً شبیه من است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000686519.mp3"},{"sentence":"The two cars are very similar in size and design.","translation":"این دو خودرو از نظر اندازه و طراحی بسیار شبیه به هم هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001585162.mp3"},{"sentence":"The two groups have broadly similar aims.","translation":"این دو گروه به طور کلی اهداف مشابهی دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001585165.mp3"},{"sentence":"The speech was strikingly similar to one given by the American president earlier this year.","translation":"این سخنرانی به طرز شگفت انگیزی شبیه سخنرانی رئیس جمهور آمریکا در اوایل سال جاری بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001585168.mp3"}]'::jsonb,8),
('631beb36-1b59-5784-9d17-a4bb137e183b','c24a8816-e4c3-50e0-a96e-10382808f79c',1,null,null,'spoken & written','the activity of breathing in tobacco smoke from a cigarette , pipe etc',null,null,'سیگار کشیدن، تفنن (بازی)؛ سیگار (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I gave up smoking nearly ten years ago.","translation":"من نزدیک به ده سال پیش سیگار را ترک کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000669536.mp3"},{"sentence":"The sign says ‘No Smoking’.","translation":"تابلو می گوید \"سیگار ممنوع\".","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000669532.mp3"},{"sentence":"a no smoking area","translation":"منطقه ممنوعه سیگار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001585917.mp3"},{"sentence":"the risks of passive smoking (= breathing in smoke from other people’s cigarettes )","translation":"خطرات سیگار کشیدن غیرفعال (= تنفس دود ناشی از سیگار دیگران)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001585918.mp3"}]'::jsonb,4),
('9a8d8b83-8e36-5a2a-b0b4-5854888cb989','cfbf8e8b-4845-5e1b-81a7-b578b5473d82',1,'people in general','مردم به طور کلی','spoken & written','people in general , considered in relation to the laws, organizations etc that make it possible for them to live together','[ uncountable ]',null,'جامعه، اجتماع؛ جامعه (علم)؛ جامعه (ایران)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"technology and its effects on modern society","translation":"تکنولوژی و تاثیرات آن بر جامعه مدرن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001625316.mp3"},{"sentence":"Children are the most vulnerable members of society .","translation":"کودکان آسیب پذیرترین اعضای جامعه هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000673572.mp3"}]'::jsonb,2),
('cbd726d0-f13a-58bf-8df6-de3f53209723','cfbf8e8b-4845-5e1b-81a7-b578b5473d82',2,'a particular group','یک گروه خاص','spoken & written','a particular large group of people who share laws, organizations, customs etc','[ countable, uncountable ]',null,'یک گروه بزرگ خاص از مردم که قوانین، سازمان ها، آداب و رسوم و غیره مشترک دارند','{}'::text[],'{}'::text[],array['a free society Censorship has no place in a free society.','a civilized society A civilized society should treat its elderly members well.','a civil society (= a society based on laws that everyone accepts ) The protection of human rights is essential for a civil society.','a multicultural/multiracial society We live in a multicultural society.','a democratic society Education is important in a democratic society.','an advanced/modern society The Greeks formed the first advanced societies in the West. This kind of hatred and violence have no place in a modern society like ours.','an industrial society In complex industrial societies, different groups specialize in particular activities.','a primitive society In almost all primitive societies, volcanoes have been regarded with fear.','a just society We are making progress towards a just society.','a classless society (= one in which people are not divided into different social classes ) the prime minister’s vision of a classless society','a capitalist society As consumers in a capitalist society, we can press companies to behave responsibly.','the larger/wider society (= used when comparing a small group of people to society as a whole ) The poor are part of the larger society, and programs must be there to help them.']::text[],'[{"sentence":"Britain is now a multiracial society.","translation":"بریتانیا اکنون یک جامعه چند نژادی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000673582.mp3"},{"sentence":"the capitalist societies of the West","translation":"جوامع سرمایه داری غرب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001625320.mp3"},{"sentence":"the conservative segment of American society","translation":"قشر محافظه کار جامعه آمریکا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001625321.mp3"}]'::jsonb,3),
('7028e2c9-edc1-503d-bc04-c5cfee1b6a73','cfbf8e8b-4845-5e1b-81a7-b578b5473d82',3,'club','باشگاه','spoken & written','an organization or club with members who share similar interests, aims etc','[ countable ]',null,'یک سازمان یا باشگاه با اعضایی که علایق، اهداف و غیره مشابهی دارند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the university film society","translation":"انجمن فیلم دانشگاه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000673598.mp3"},{"sentence":"the American Cancer Society","translation":"انجمن سرطان آمریکا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000673599.mp3"},{"sentence":"the Society of Black Lawyers","translation":"انجمن وکلای سیاه پوست","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001780197.mp3"}]'::jsonb,3),
