('1756a66a-4a65-5f05-a5eb-26524a9f33d9','2aced357-25d1-57c5-9d8b-ca0c1ad9437f',1,null,null,'spoken & written','in some way, or by some means , although you do not know how',null,null,'به نحوی، به‌طور متفاوتی؛ با گونه‌ای','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Don’t worry, we’ll get the money back somehow.","translation":"نگران نباشید، ما پول را به نحوی پس خواهیم گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648523.mp3"},{"sentence":"Somehow, I managed to lose my keys.","translation":"به نوعی موفق شدم کلیدهایم را گم کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633693.mp3"},{"sentence":"Maybe we could glue it together somehow or other .","translation":"شاید بتوانیم به نحوی آن را به هم بچسبانیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633694.mp3"}]'::jsonb,3),
