('f12b78e4-1297-5066-a95a-1960a3ec7a28','1b03f686-c9e0-5d85-a098-717b0638360c',1,null,null,'spoken & written','used to mean a person , when you do not know or do not say who the person is',null,null,'کسی، شخص (ناشناس)؛ فرد (غیرمعلوم)',array['somebody']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"What would you do if someone tried to rob you in the street?","translation":"اگر کسی بخواهد در خیابان از شما دزدی کند چه می کنید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648543.mp3"},{"sentence":"Will someone please explain what’s going on?","translation":"آیا کسی لطفا توضیح دهد که جریان چیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648544.mp3"},{"sentence":"‘When are you planning to hire someone?’ ‘As soon as we find someone suitable.’","translation":"\"چه زمانی قصد دارید کسی را استخدام کنید؟\" \"به محض اینکه کسی مناسب را پیدا کنیم.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648547.mp3"},{"sentence":"Can you ask someone else (= a different person ) to help you? I’m really busy.","translation":"آیا می توانید از شخص دیگری (= فرد متفاوت) بخواهید که به شما کمک کند؟ من واقعا سرم شلوغه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633699.mp3"},{"sentence":"Have Brooks or someone fax this to New York right away.","translation":"از بروکس یا شخصی بخواهید این را فوراً به نیویورک فکس کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633704.mp3"}]'::jsonb,5),
