('5b0edbc5-49e5-5969-b01c-e626356b69c7','e22eeb04-27aa-558e-b8ae-58fe62f36bc0',3,null,null,'spoken & written','a special position or job has a particular purpose or aim , and continues only until that purpose or aim is achieved','[ only before noun ]',null,'یک موقعیت یا شغل خاص هدف یا هدف خاصی دارد و تنها تا زمانی ادامه می یابد که آن هدف یا هدف محقق شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Mitchell acted as a special envoy in the Northern Ireland peace talks.","translation":"میچل به عنوان فرستاده ویژه در مذاکرات صلح ایرلند شمالی عمل کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001623519.mp3"}]'::jsonb,1),
