('64c7e6b9-a585-53aa-93ed-3efb15dc9eee','c33d9835-707f-5881-b6df-5ff7b9bc3d05',1,null,null,'spoken & written','unusual or surprising , especially in a way that is difficult to explain or understand',null,null,'عجیب، شگفت‌آور؛ ناشناخته (حس)؛ غریبه (فرد)',array['odd']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"strange noises","translation":"صداهای عجیب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000619206.mp3"},{"sentence":"Does Geoff’s behaviour seem strange to you?","translation":"آیا رفتار جف برای شما عجیب به نظر می رسد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000619207.mp3"},{"sentence":"She felt there was something strange about Dexter’s voice.","translation":"او احساس کرد چیزی عجیب در صدای دکستر وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001599994.mp3"},{"sentence":"Isn’t it strange how animals seem to sense danger?","translation":"آیا عجیب نیست که حیوانات چگونه خطر را احساس می کنند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001599998.mp3"},{"sentence":"It’s strange that we’ve never met before.","translation":"عجیب است که ما قبلاً ملاقات نکرده بودیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600002.mp3"},{"sentence":"For some strange reason , I slept like a baby despite the noise.","translation":"به دلایلی عجیب با وجود سر و صدا مثل یک بچه خوابیدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600005.mp3"},{"sentence":"Strange as it may seem , I actually prefer cold weather.","translation":"هر چند ممکن است عجیب به نظر برسد، من در واقع هوای سرد را ترجیح می دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600008.mp3"},{"sentence":"That’s strange . I was sure Jude was right here a second ago.","translation":"این عجیب است. مطمئن بودم که جود یک ثانیه پیش اینجاست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000619211.mp3"},{"sentence":"The strange thing is all four victims had red hair.","translation":"نکته عجیب این است که هر چهار قربانی موهای قرمز داشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600014.mp3"},{"sentence":"Strange to say, I was just thinking that myself.","translation":"عجیب است، من فقط به این فکر می کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000619222.mp3"}]'::jsonb,10),
('86e85b4f-d683-5f7d-9995-c1ab55c66a4b','c33d9835-707f-5881-b6df-5ff7b9bc3d05',2,null,null,'spoken & written','someone or something that is strange is not familiar because you have not seen or met them before',null,null,'کسی یا چیزی که عجیب است آشنا نیست زیرا قبلاً آنها را ندیده اید یا ملاقات نکرده اید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"As a child, she’d been taught never to speak to strange men.","translation":"در کودکی به او آموخته بودند که هرگز با مردان غریبه صحبت نکند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600015.mp3"},{"sentence":"I was just 20, a young girl in a strange city.","translation":"من فقط 20 ساله بودم، دختری جوان در شهری غریب.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600016.mp3"},{"sentence":"It was all strange to him, but he’d soon learn his way around.","translation":"همه چیز برای او عجیب بود، اما او به زودی راه خود را یاد می گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600019.mp3"}]'::jsonb,3),
