('a62ef34f-a9dd-5326-a7fc-e92690aa83b2','a3ad21da-7130-5cdb-814f-41f553fd579a',1,'make something bigger/looser','چیزی بزرگتر / شل تر بساز','spoken & written','to make something bigger or looser by pulling it, or to become bigger or looser as a result of being pulled','[ intransitive, transitive ]',null,'کشیدن، کشانیدن (بافت)؛ کشیدن (بدن)؛ کشش (بافت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A spider’s web can stretch considerably without weakening.","translation":"تار عنکبوت می تواند به طور قابل توجهی بدون ضعیف شدن کشیده شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001669535.mp3"},{"sentence":"Where can I buy those things that stretch your shoes?","translation":"از کجا می توانم چیزهایی را بخرم که کفش های شما را کش می دهد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001669536.mp3"}]'::jsonb,2),
('96961085-93dd-54da-a41e-61563de9fc0b','a3ad21da-7130-5cdb-814f-41f553fd579a',2,'body','بدن','spoken & written','to straighten your arms, legs, or body to full length','[ intransitive, transitive ]',null,'تا دست ها، پاها یا بدن خود را به اندازه کامل صاف کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Carl sat up in bed, yawned, and stretched.","translation":"کارل روی تخت نشست، خمیازه کشید و دراز کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000620773.mp3"},{"sentence":"Always stretch before exercising.","translation":"همیشه قبل از ورزش حرکات کششی انجام دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001669537.mp3"}]'::jsonb,2),
('105dd4d7-07a1-573e-be8c-7588e1b2df28','a3ad21da-7130-5cdb-814f-41f553fd579a',3,'reach','رسیدن','spoken & written','to reach a long way for something','[ intransitive always +adv/preposition ]',null,'رسیدن به راهی طولانی برای چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Ann stretched across the couch and grabbed the phone.","translation":"ان روی مبل دراز کشید و گوشی را گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001669545.mp3"}]'::jsonb,1),
