('74824c00-22ae-5a92-913f-72c0635a7a5e','a3ad21da-7130-5cdb-814f-41f553fd579a',5,'time/series','زمان/سریال','spoken & written','to continue over a period of time or in a series , or to make something do this','[ intransitive, transitive always + adverb/preposition ]',null,'ادامه دادن در یک دوره زمانی یا در یک سری، یا کاری برای انجام این کار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Berg’s career as a government official stretched over 20 years.","translation":"حرفه برگ به عنوان یک مقام دولتی بیش از 20 سال طول کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040253.mp3"},{"sentence":"With a goal in the second half, Spurs stretched their lead to 3–0.","translation":"اسپرز با یک گل در نیمه دوم اختلاف خود را به 3-0 رساند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001669548.mp3"}]'::jsonb,2),
('2167f8ff-b0da-5ad3-940b-1581b99ccf9f','a3ad21da-7130-5cdb-814f-41f553fd579a',6,'in space','در فضا','spoken & written','to spread out or cover a large area of land','[ intransitive always + adverb/preposition ]',null,'برای گسترش یا پوشاندن سطح وسیعی از زمین','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Row after row of orange trees stretched to the horizon.","translation":"ردیف به ردیف درختان پرتقال تا افق کشیده شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001669549.mp3"},{"sentence":"a line stretching around the block","translation":"خطی که در اطراف بلوک کشیده شده است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000620791.mp3"}]'::jsonb,2),
