('d0607caa-f894-5aba-92e6-a1e0142d2d05','a82c91b2-c0a1-5a87-a8dd-8ed876bfb154',3,'body','بدن','spoken & written','the action of stretching a part of your body out to its full length, or a particular way of doing this','[ countable ]',null,'عمل کشش بخشی از بدن تا تمام طول آن، یا روش خاصی برای انجام این کار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The ski instructor showed us some special stretches.","translation":"مربی اسکی کشش های خاصی را به ما نشان داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000620899.mp3"}]'::jsonb,1),
