('87a98e35-335d-5d09-b537-873e74a18307','de3470a0-22c7-5e32-8387-49dcea834152',1,null,null,'spoken & written','to do what you tried or wanted to do','[ intransitive ]',null,'موفق شدن، به هدف رسیدن (در)؛ جانشین شدن (در)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She wanted to be the first woman to climb Mount Everest, and she almost succeeded.","translation":"او می خواست اولین زنی باشد که به قله اورست صعود می کند و تقریباً موفق شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001538.mp3"},{"sentence":"Scientists claim they have succeeded in finding a cure for cancer.","translation":"دانشمندان ادعا می کنند که موفق به یافتن درمانی برای سرطان شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001539.mp3"},{"sentence":"Very few people succeed in losing weight and keeping it off.","translation":"افراد بسیار کمی موفق به کاهش وزن و حفظ آن می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001743159.mp3"},{"sentence":"Eventually I managed to get the lid back on the box.","translation":"در نهایت موفق شدم درب جعبه را برگردانم.","audio_url":null},{"sentence":"She succeeded in persuading him.","translation":"او موفق شد او را متقاعد کند.","audio_url":null},{"sentence":"I hope you succeed.","translation":"امیدوارم موفق بشی","audio_url":null}]'::jsonb,6),
('32615da3-3abf-5a88-bc40-de31cbcb268a','de3470a0-22c7-5e32-8387-49dcea834152',2,null,null,'spoken & written','to have the result or effect something was intended to have','[ intransitive ]',null,'داشتن نتیجه یا تأثیر چیزی که قرار بود داشته باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Unfortunately his plan did not succeed.","translation":"متاسفانه نقشه او به نتیجه نرسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00855.mp3"},{"sentence":"We tried rebooting the computer, but that didn’t work .","translation":"ما سعی کردیم کامپیوتر را راه اندازی مجدد کنیم، اما کار نکرد.","audio_url":null}]'::jsonb,2),
('13a9e22d-5011-5e52-9369-72b13bb8450d','de3470a0-22c7-5e32-8387-49dcea834152',3,null,null,'spoken & written','to do well in your job, especially because you have worked hard at it for a long time','[ intransitive ]',null,'در کار خود به خوبی انجام دهید، به خصوص به این دلیل که برای مدت طولانی روی آن کار کرده اید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m not sure he has the determination to succeed as an actor.","translation":"من مطمئن نیستم که او اراده ای برای موفقیت به عنوان یک بازیگر داشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000627453.mp3"},{"sentence":"a woman who succeeded in politics","translation":"زنی که در سیاست موفق شد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000627456.mp3"}]'::jsonb,2),
