('60035725-db1f-55ba-b6bf-fdcbbf934e65','dac766a8-e586-5c78-a37d-d1b521da3eda',7,null,null,'spoken & written','to think that something is probably true, based on what you know',null,null,'بر اساس آنچه می دانید فکر کنید که احتمالاً چیزی درست است',array['presume']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There were many more deaths than was first supposed.","translation":"تعداد تلفات بسیار بیشتر از آنچه در ابتدا تصور می شد وجود داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000600953.mp3"},{"sentence":"What makes you suppose we’re going to sell the house?","translation":"چه چیزی باعث می شود فکر کنید ما خانه را می فروشیم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612503.mp3"},{"sentence":"There’s no reason to suppose (= it is unlikely that ) he’s lying.","translation":"دلیلی وجود ندارد که فرض کنیم (= بعید است که) دروغ می گوید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000600964.mp3"},{"sentence":"It is usually supposed that girls are less aggressive than boys.","translation":"معمولاً فرض بر این است که دختران نسبت به پسرها پرخاشگرتر هستند.","audio_url":null}]'::jsonb,4),
('e4fb75e0-eba5-508f-a635-8f0d2eb1e09c','dac766a8-e586-5c78-a37d-d1b521da3eda',8,null,null,'formal','to expect that something will happen or be true, and to base your plans on it',null,null,'انتظار داشته باشید که چیزی اتفاق بیفتد یا واقعیت داشته باشد و برنامه های خود را بر اساس آن قرار دهید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The company’s plan supposes a steady increase in orders.","translation":"برنامه این شرکت افزایش مداوم سفارشات را در نظر می گیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000600969.mp3"}]'::jsonb,1),
('90f83dc7-d828-5c61-83e4-1e5c1f3c81f4','20f72ffb-9945-5f62-a203-56f1605f0b12',1,'water/land','آب/زمین','spoken & written','the top layer of an area of water or land',null,null,'سطح، رویه (سطح)؛ سطح (بازار)؛ سطح (آب)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Dead leaves floated on the surface of the water.","translation":"برگ های مرده روی سطح آب شناور بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612638.mp3"},{"sentence":"Nearly 10% of the Earth’s surface is covered by ice.","translation":"نزدیک به 10 درصد از سطح زمین را یخ پوشانده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040259.mp3"},{"sentence":"Gas bubbles in any liquid tend to rise to the surface .","translation":"حباب های گاز در هر مایعی تمایل به بالا رفتن به سطح دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612642.mp3"},{"sentence":"The tunnel was some 300 feet below the surface.","translation":"تونل حدود 300 فوت زیر سطح بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612648.mp3"}]'::jsonb,4),
('b4c76df6-0eeb-53de-b996-e967f38e15f9','20f72ffb-9945-5f62-a203-56f1605f0b12',2,'outside/top layer','لایه بیرونی/بالایی','spoken & written','the outside or top layer of something',null,null,'لایه بیرونی یا بالای چیزی','{}'::text[],'{}'::text[],array['the upper/top surface The upper surface of the leaf is dull green.','the outer/inner surface The outer surface of the shell is ridged.','smooth Marble provides a cool smooth surface.','rough I reached out and touched the rough surface of the stone wall.','textured (= not smooth, because of its design ) Many floor tiles have textured surfaces to make them less slippery underfoot.','hard The path has a hard surface suitable for wheelchairs and pushchairs.','shiny This type of cloth has a shiny surface on one side.','polished I didn''t want to spill anything on the polished surface of the table.','slippery The sign read: ‘Beware: slippery surface.’','flat Put the compass on a flat surface.']::text[],'[{"sentence":"the surface of the vase","translation":"سطح گلدان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612657.mp3"},{"sentence":"The road surfaces tend to be worse in the towns than in the country.","translation":"سطح جاده ها در شهرها بدتر از کشور است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612658.mp3"},{"sentence":"a frying pan with a non-stick surface","translation":"یک ماهیتابه با سطح نچسب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000601741.mp3"},{"sentence":"mold growing on the cheese’s surface","translation":"رشد کپک روی سطح پنیر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612664.mp3"}]'::jsonb,4),
