('5529c8d7-d99e-560c-ada4-ed700b1c6d45','20f72ffb-9945-5f62-a203-56f1605f0b12',4,'for working on','برای کار بر روی','spoken & written','a flat area on the top of a cupboard , table, desk etc, that you use for cooking or working on',null,null,'یک قسمت صاف در بالای کمد، میز، میز و غیره که برای پخت و پز یا کار روی آن استفاده می کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Keep kitchen surfaces clean and tidy.","translation":"سطوح آشپزخانه را تمیز و مرتب نگه دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000601761.mp3"},{"sentence":"Work on a clean, flat surface.","translation":"روی یک سطح تمیز و صاف کار کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612686.mp3"}]'::jsonb,2),
('fd6322e6-4372-5eb9-b83b-afae9515be8e','20f72ffb-9945-5f62-a203-56f1605f0b12',5,'side of an object','طرف یک شی','spoken & written','one of the sides of an object',null,null,'یکی از اضلاع یک جسم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"How many surfaces does a cube have?","translation":"یک مکعب چند سطح دارد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000601767.mp3"}]'::jsonb,1),
('39f1f51e-38d1-5393-a93b-90bd4f49a446','7b7c1006-b038-5793-8e82-e6fa1b41e841',1,null,null,'spoken & written','if information, feelings , or problems surface, they become known about or easy to notice','[ intransitive ]',null,'اگر اطلاعات، احساسات یا مشکلات ظاهر شوند، در مورد آنها شناخته شده یا به راحتی قابل توجه هستند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Rumors about the killings have begun to surface in the press.","translation":"شایعات در مورد این قتل در مطبوعات شروع شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612690.mp3"},{"sentence":"the jealousy that had surfaced in her","translation":"حسادتی که در او ظاهر شده بود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612694.mp3"}]'::jsonb,2),
('33418b9d-7bd6-5989-96c9-f7752c44e6ba','7b7c1006-b038-5793-8e82-e6fa1b41e841',2,null,null,'spoken & written','if someone or something surfaces, they suddenly appear somewhere, especially after being gone or hidden for a long time','[ intransitive ]',null,'اگر کسی یا چیزی ظاهر شود، به طور ناگهانی در جایی ظاهر می شود، به خصوص پس از اینکه برای مدت طولانی رفته یا پنهان شده است.',array['pop up']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Last year Toole surfaced again in Cuba.","translation":"سال گذشته تول دوباره در کوبا ظاهر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612695.mp3"}]'::jsonb,1),
('4c0aefc9-5a26-5b5b-a1ea-218ae6f5c44d','7b7c1006-b038-5793-8e82-e6fa1b41e841',3,null,null,'spoken & written','to rise to the surface of water','[ intransitive ]',null,'برای بالا آمدن به سطح آب','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"divers surfacing near the boat","translation":"غواصان در نزدیکی قایق ظاهر می شوند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000601785.mp3"}]'::jsonb,1),
('5c49c1c0-4d2b-54f8-b17a-64d73fc192ed','7b7c1006-b038-5793-8e82-e6fa1b41e841',4,null,null,'informal','to get out of bed , especially late','[ intransitive ]',null,'برای بلند شدن از رختخواب مخصوصا دیر وقت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Joe never surfaces before midday on Sunday.","translation":"جو هرگز قبل از ظهر یکشنبه ظاهر نمی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001612703.mp3"}]'::jsonb,1),
