('2bc26013-20a8-5f76-8be5-108317c7cd13','6f2be1d9-642e-5c85-9e1a-f35c569bd5fd',4,null,null,'spoken & written','likely to contain a bomb or something illegal or dangerous','[ only before noun ]',null,'احتمالا حاوی بمب یا چیزی غیرقانونی یا خطرناک است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Police were called in to check out a suspect van.","translation":"پلیس برای بررسی یک ون مشکوک فراخوانده شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000602971.mp3"}]'::jsonb,1),
('73070c0d-c9c5-5a20-8a50-58238c2475a4','ca1c09ef-2ee2-5565-af36-3c3c46c1cad1',1,'make something continue','کاری کن که ادامه پیدا کنه','spoken & written','to make something continue to exist or happen for a period of time',null,'sustained','پایدار نگه داشتن، بقا داشتن (شرکت)؛ تأمین کردن (نیاز)؛ تحمل کردن (حالت)',array['maintain']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She found it difficult to sustain the children’s interest.","translation":"برای او حفظ علاقه کودکان دشوار بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000603311.mp3"},{"sentence":"He was incapable of sustaining close relationships with women.","translation":"او قادر به حفظ روابط نزدیک با زنان نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001577422.mp3"},{"sentence":"the policies necessary to sustain economic growth","translation":"سیاست های لازم برای حفظ رشد اقتصادی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001577423.mp3"}]'::jsonb,3),
('7c9fd9fa-94c8-58da-a2df-ecaf787490d0','ca1c09ef-2ee2-5565-af36-3c3c46c1cad1',2,'suffer','رنج می برند','formal','to suffer damage , an injury , or loss of money',null,null,'برای متحمل شدن آسیب، جراحت یا از دست دادن پول','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Two of the firefighters sustained serious injuries.","translation":"دو تن از آتش نشانان به شدت مجروح شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001577425.mp3"},{"sentence":"Some nearby buildings sustained minor damage.","translation":"برخی از ساختمان های مجاور آسیب جزئی دیده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001577431.mp3"},{"sentence":"The company has sustained heavy financial losses this year.","translation":"این شرکت در سال جاری خسارات مالی سنگینی متحمل شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001577437.mp3"}]'::jsonb,3),
('a26a4b73-97df-5de0-aade-b6d617e4cf04','ca1c09ef-2ee2-5565-af36-3c3c46c1cad1',3,'food/drink','غذا/نوشیدنی','formal','if food or drink sustains a person, animal , or plant , it makes them able to continue living',null,null,'اگر غذا یا نوشیدنی انسان، حیوان یا گیاه را حفظ کند، باعث می شود که بتواند به زندگی ادامه دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They gave me barely enough food to sustain me.","translation":"آنها به سختی به من غذای کافی برای نگهداریم دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001577447.mp3"}]'::jsonb,1),
('28b903b2-8b7b-5954-9f6c-57cc4a748339','ca1c09ef-2ee2-5565-af36-3c3c46c1cad1',4,'give strength','قدرت دادن','formal','to make someone feel strong and hopeful',null,null,'تا کسی احساس قوی و امیدوار کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The thought of seeing her again was all that sustained me.","translation":"فکر دیدن دوباره او تنها چیزی بود که مرا حفظ کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000603321.mp3"}]'::jsonb,1),
('c7955dbc-c34b-5619-acee-a5f178791a9b','ca1c09ef-2ee2-5565-af36-3c3c46c1cad1',5,'weight','وزن','formal','to hold up the weight of something',null,null,'تحمل وزن چیزی',array['support']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He leant against her so heavily that she could barely sustain his weight.","translation":"چنان به او تکیه داد که به سختی وزنش را حفظ کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000603333.mp3"}]'::jsonb,1),
('62fc9c16-3106-5edf-bf60-2f04d00844fb','ca1c09ef-2ee2-5565-af36-3c3c46c1cad1',6,'idea','ایده','formal','to support an idea or argument , or prove that it is right',null,null,'برای حمایت از یک ایده یا استدلال، یا اثبات درست بودن آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This argument is difficult to sustain.","translation":"حفظ این استدلال دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000603339.mp3"}]'::jsonb,1),
('0c484d38-1888-5b5c-a1e4-f7c6e3677dd2','5e89bf2a-d80a-522f-b5b5-85bc77732edd',1,null,null,'spoken & written','someone whose job is to teach , especially in a school',null,null,'معلم، آموزگار؛ استاد (دبستان)؛ مدرس (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a primary school teacher","translation":"معلم دبستان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000584027.mp3"}]'::jsonb,1),
('bf338076-a465-5bd8-ac61-d32d4114cc96','14cefd7e-25f5-581f-822d-25193e996e7d',1,'nervous feeling','احساس عصبی','spoken & written','a nervous worried feeling that makes it impossible for you to relax','[ uncountable ]',null,'تنش، کشمکش؛ تنش (ماهیچه)؛ تنش (روانی)','{}'::text[],'{}'::text[],array['unbearable The tension was almost unbearable by the time we reached the decisive last round.','nervous tension The night before the wedding my mother was in a state of nervous tension.','high tension There was a moment of high tension as the firemen entered the burning building.','dramatic tension (= the tension you feel when you are not sure quite what will happen in a story ) This uncertainty adds to the film’s dramatic tension.','reduce/ease/relieve tension Breathing deeply helps to clear my mind and reduce tension.','sense the tension She could sense the tension in the room.','a state of tension Marjorie lived in a constant state of tension waiting for his phone calls.','an atmosphere of tension Voting took place in an atmosphere of tension.']::text[],'[{"sentence":"The tension was becoming unbearable, and I wanted to scream.","translation":"تنش غیر قابل تحمل می شد و من می خواستم فریاد بزنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000590797.mp3"},{"sentence":"Exercise is the ideal way to relieve tension after a hard day.","translation":"ورزش راهی ایده آل برای کاهش تنش پس از یک روز سخت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001616751.mp3"}]'::jsonb,2),
('cebe4906-109c-5266-b6ca-0fe3e3b82ffa','14cefd7e-25f5-581f-822d-25193e996e7d',2,'no trust','بدون اعتماد','spoken & written','the feeling that exists when people or countries do not trust each other and may suddenly attack each other or start arguing','[ countable usually plural, uncountable ]',null,'احساسی که زمانی ایجاد می شود که مردم یا کشورها به یکدیگر اعتماد ندارند و ممکن است ناگهان به یکدیگر حمله کنند یا شروع به مشاجره کنند.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"In those days, there was a great deal of racial tension on campus.","translation":"در آن روزها تنش نژادی زیادی در دانشگاه وجود داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001616752.mp3"},{"sentence":"The obvious tension between Warren and Anne made everyone else uncomfortable.","translation":"تنش آشکار بین وارن و آن همه را ناراحت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001585.mp3"}]'::jsonb,2),
('611cfeb7-d7ce-5859-bfbf-8da0c1f0073d','14cefd7e-25f5-581f-822d-25193e996e7d',3,'different influences','تاثیرات مختلف','spoken & written','if there is tension between two things, there is a difference between the needs or influences of each, and that causes problems','[ countable, uncountable ]',null,'اگر بین دو چیز تنش وجود داشته باشد، بین نیازها یا تأثیرات هر یک تفاوت وجود دارد و باعث ایجاد مشکل می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"In business, there’s always a tension between the needs of customers and shareholders.","translation":"در تجارت، همیشه تنش بین نیازهای مشتریان و سهامداران وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000590811.mp3"}]'::jsonb,1),
('02f9b347-aa22-5771-bdec-719e424000e8','14cefd7e-25f5-581f-822d-25193e996e7d',4,'tightness','تنگی','spoken & written','tightness or stiffness in a wire , rope , muscle etc','[ uncountable ]',null,'سفتی یا سفتی در سیم، طناب، ماهیچه و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Tension in the neck muscles can cause headaches.","translation":"تنش در عضلات گردن می تواند باعث سردرد شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000590817.mp3"},{"sentence":"Muscle tension can be a sign of stress.","translation":"تنش عضلانی می تواند نشانه استرس باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001616757.mp3"}]'::jsonb,2),
('31d6a2ce-84e0-5a7a-a4e5-3c8a4fc7b45c','14cefd7e-25f5-581f-822d-25193e996e7d',5,'force','زور','spoken & written','the amount of force that stretches something','[ uncountable ]',null,'مقدار نیرویی که چیزی را کشش می دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This wire will take 50 pounds tension.","translation":"این سیم کشش 50 پوندی خواهد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000590823.mp3"},{"sentence":"There was a lot of tension on the wire before it snapped.","translation":"قبل از شکستن سیم کشش زیادی داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001616762.mp3"}]'::jsonb,2),
('456da400-9832-5dd4-b92d-4ae4aa2c0485','f6cee8cf-d75b-5e30-99d7-fddd301be7f6',1,'building','ساختمان','spoken & written','a building or place with a stage where plays and shows are performed','[ countable ]',null,'تئاتر، سالن نمایش؛ تئاتر (کار)؛ سینما (بریتانیایی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an open-air theatre (= a theatre that is outside )","translation":"تئاتر در فضای باز (= تئاتری که بیرون است)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001629061.mp3"},{"sentence":"the Mercury Theater","translation":"تئاتر مرکوری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000593924.mp3"}]'::jsonb,2),
('3ebd7ee5-839f-57bd-9a80-ab6f67ddc2d7','f6cee8cf-d75b-5e30-99d7-fddd301be7f6',2,'plays','بازی می کند','spoken & written','plays as a form of entertainment','[ uncountable ]',null,'به عنوان نوعی سرگرمی بازی می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I enjoy theater and swimming.","translation":"من از تئاتر و شنا لذت می برم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000593931.mp3"},{"sentence":"He’s really interested in literature and the theatre.","translation":"او واقعاً به ادبیات و تئاتر علاقه مند است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000593934.mp3"},{"sentence":"Yeats’ plays are great poetry but they are not good theatre (= good entertainment ) .","translation":"نمایشنامه های ییتس شعر عالی هستند اما تئاتر خوبی نیستند (= سرگرمی خوب).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000593938.mp3"},{"sentence":"classes in theater and music","translation":"کلاس های تئاتر و موسیقی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000593942.mp3"},{"sentence":"She’s been working in the theatre over thirty years.","translation":"او بیش از سی سال در تئاتر کار می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000593943.mp3"}]'::jsonb,5),
('cf00fe30-55a0-5278-b223-85fc6585b3ed','f6cee8cf-d75b-5e30-99d7-fddd301be7f6',3,'place to see a film','مکانی برای دیدن فیلم','spoken & written','a building where films are shown','[ countable ]',null,'ساختمانی که در آن فیلم نمایش داده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Bambi’ was the first movie I ever saw in the theater.","translation":"«بامبی» اولین فیلمی بود که در سینما دیدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001629075.mp3"}]'::jsonb,1),
('1800640a-47d8-5232-a9d7-65d4aad5291b','f6cee8cf-d75b-5e30-99d7-fddd301be7f6',4,'hospital','بیمارستان','spoken & written','a special room in a hospital where medical operations are done','[ countable, uncountable ]',null,'یک اتاق ویژه در یک بیمارستان که در آن عملیات پزشکی انجام می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Marilyn is still in theatre.","translation":"مرلین هنوز در تئاتر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001629079.mp3"}]'::jsonb,1),
('c6bbdb23-b185-5155-9d0d-471cea0073e4','f6cee8cf-d75b-5e30-99d7-fddd301be7f6',5,'war','جنگ','formal','a large area where a war is being fought','[ countable ]',null,'منطقه بزرگی که در آن جنگ در حال وقوع است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the Pacific theater during World War II","translation":"تئاتر اقیانوس آرام در طول جنگ جهانی دوم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000593958.mp3"}]'::jsonb,1),
('9ec2de80-1c13-5e2c-998f-09a5050742ec','b687e857-2c4b-5c32-bda8-f28a4bac18c7',1,null,null,'spoken & written','the past tense and past participle of think 1',null,null,'فکر، اندیشه؛ فکر (کار)؛ اندیشه (فرد)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('f24820c3-5177-5cba-a668-df27ccb8af3b','98cc541d-5da1-5f08-bccf-5b9c35769d97',1,'something you think about','چیزی که بهش فکر میکنی','spoken & written','something that you think of, remember , or realize','[ countable ]',null,'چیزی که به آن فکر می کنید، به یاد می آورید یا متوجه می شوید',array['idea']::text[],'{}'::text[],array['have a thought I just had a funny thought.','express your thoughts (= say what they are or tell other people about them ) He was finding it difficult to express his thoughts.','a thought occurs to/comes to/strikes somebody (= someone suddenly has a thought ) The thought occurred to him that she might be lying.','a thought crosses somebody’s mind (= someone has a thought ) The thought never crossed my mind that I could be wrong.','can’t bear the thought of something I can’t bear the thought of you being hurt.','somebody’s thoughts turn to something (= they start thinking about something ) As summer approaches, people’s thoughts turn to holidays.','somebody’s first thought My first thought was that a bomb had gone off.','a passing thought (= a quick, not very serious thought ) He never gives his appearance more than a passing thought.','a sobering thought (= one that makes you feel serious ) We have the power to destroy the world, which is a sobering thought.','horrible/disturbing A horrible thought struck her: could he be having an affair?','a comforting thought ‘People might not have noticed we’re late.’ ‘That’s a comforting thought.’','a sudden thought A sudden thought struck her and she began to laugh.','the very thought (= even the idea of doing something ) The very thought of going on stage made her feel ill.']::text[],'[{"sentence":"It’s an interesting thought.","translation":"فکر جالبی است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001610.mp3"},{"sentence":"The thought that I might not have a job next year is a bit troubling.","translation":"این فکر که ممکن است سال آینده شغلی نداشته باشم کمی نگران کننده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001611.mp3"}]'::jsonb,2),
('6dc9b9b4-4c5b-5329-9ff6-6cc915df0dc8','98cc541d-5da1-5f08-bccf-5b9c35769d97',2,null,null,'spoken & written',null,null,'thoughts','فکر، اندیشه؛ فکر (کار)؛ اندیشه (فرد)','{}'::text[],'{}'::text[],array['have a thought I just had a funny thought.','express your thoughts (= say what they are or tell other people about them ) He was finding it difficult to express his thoughts.','a thought occurs to/comes to/strikes somebody (= someone suddenly has a thought ) The thought occurred to him that she might be lying.','a thought crosses somebody’s mind (= someone has a thought ) The thought never crossed my mind that I could be wrong.','can’t bear the thought of something I can’t bear the thought of you being hurt.','somebody’s thoughts turn to something (= they start thinking about something ) As summer approaches, people’s thoughts turn to holidays.','somebody’s first thought My first thought was that a bomb had gone off.','a passing thought (= a quick, not very serious thought ) He never gives his appearance more than a passing thought.','a sobering thought (= one that makes you feel serious ) We have the power to destroy the world, which is a sobering thought.','horrible/disturbing A horrible thought struck her: could he be having an affair?','a comforting thought ‘People might not have noticed we’re late.’ ‘That’s a comforting thought.’','a sudden thought A sudden thought struck her and she began to laugh.','the very thought (= even the idea of doing something ) The very thought of going on stage made her feel ill.']::text[],'[]'::jsonb,0),
('58d60ff1-5194-593a-bb96-7d63752466f6','98cc541d-5da1-5f08-bccf-5b9c35769d97',3,'careful consideration','بررسی دقیق','spoken & written','careful and serious consideration','[ uncountable ]',null,'بررسی دقیق و جدی','{}'::text[],'{}'::text[],array['have a thought I just had a funny thought.','express your thoughts (= say what they are or tell other people about them ) He was finding it difficult to express his thoughts.','a thought occurs to/comes to/strikes somebody (= someone suddenly has a thought ) The thought occurred to him that she might be lying.','a thought crosses somebody’s mind (= someone has a thought ) The thought never crossed my mind that I could be wrong.','can’t bear the thought of something I can’t bear the thought of you being hurt.','somebody’s thoughts turn to something (= they start thinking about something ) As summer approaches, people’s thoughts turn to holidays.','somebody’s first thought My first thought was that a bomb had gone off.','a passing thought (= a quick, not very serious thought ) He never gives his appearance more than a passing thought.','a sobering thought (= one that makes you feel serious ) We have the power to destroy the world, which is a sobering thought.','horrible/disturbing A horrible thought struck her: could he be having an affair?','a comforting thought ‘People might not have noticed we’re late.’ ‘That’s a comforting thought.’','a sudden thought A sudden thought struck her and she began to laugh.','the very thought (= even the idea of doing something ) The very thought of going on stage made her feel ill.']::text[],'[{"sentence":"With more thought and care this would have been a first-class essay.","translation":"با فکر و دقت بیشتر، این یک مقاله درجه یک بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000566564.mp3"},{"sentence":"I’ve been giving your proposal a lot of thought.","translation":"من در مورد پیشنهاد شما بسیار فکر کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000566568.mp3"},{"sentence":"Have you given any more thought to going back to school?","translation":"آیا دیگر به بازگشت به مدرسه فکر کرده اید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644978.mp3"}]'::jsonb,3),
