('3d84e2e1-53fe-5ed3-a75b-fc97cd52238f','4ad11425-aa7d-58ab-aad4-848c0ef11d4e',1,'door/passage etc','درب / گذرگاه و غیره','spoken & written','into one side or end of an entrance , passage , hole etc and out of the other side or end',null,null,'از میان، از درونِ؛ از راهِ (دریچه)؛ از طریقِ','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She smiled at him as he walked through the door.","translation":"در حالی که از در عبور می کرد به او لبخند زد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591350.mp3"},{"sentence":"Water will be pumped through a pipe.","translation":"آب از طریق یک لوله پمپ می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841724.mp3"},{"sentence":"I managed to squeeze through a gap in the hedge.","translation":"موفق شدم از شکاف پرچین عبور کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591353.mp3"},{"sentence":"They were suddenly plunged into darkness as the train went through a tunnel.","translation":"آنها ناگهان در تاریکی فرو رفتند که قطار از یک تونل عبور می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000567879.mp3"},{"sentence":"There were people standing in the doorway and I couldn’t get through.","translation":"افرادی در آستانه در ایستاده بودند و من نمی توانستم از آن عبور کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841725.mp3"},{"sentence":"I went through to the kitchen to see who was there.","translation":"رفتم تو آشپزخونه ببینم کی هست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841728.mp3"}]'::jsonb,6),
('4fc77f02-2b06-5ea6-bee1-8284bf822449','4ad11425-aa7d-58ab-aad4-848c0ef11d4e',2,'cutting/breaking','بریدن/شکستن','spoken & written','cutting or breaking something, or making a hole from one side of it to the other',null,null,'بریدن یا شکستن چیزی یا ایجاد سوراخ از یک طرف آن به طرف دیگر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A football came crashing through the window.","translation":"یک توپ فوتبال از پنجره سقوط کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591355.mp3"},{"sentence":"The bullet passed straight through his skull.","translation":"گلوله مستقیماً از جمجمه اش عبور کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841731.mp3"}]'::jsonb,2),
('60059df4-837a-584f-afea-4de3996ddb49','4ad11425-aa7d-58ab-aad4-848c0ef11d4e',3,'across an area','در سراسر یک منطقه','spoken & written','from one side of an area to the other or between a group of things',null,null,'از یک طرف یک منطقه به طرف دیگر یا بین گروهی از چیزها','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We passed through France on our way to Italy.","translation":"در راه ایتالیا از فرانسه گذشتیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841733.mp3"},{"sentence":"We made our way through the village to the farm.","translation":"ما از طریق روستا به مزرعه رسیدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591370.mp3"},{"sentence":"The wind howled through the trees.","translation":"باد از میان درختان زوزه می کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591373.mp3"},{"sentence":"He had to push his way through the crowd to get to her.","translation":"مجبور شد راهش را در میان جمعیت رد کند تا به او برسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000567885.mp3"},{"sentence":"Let me through – I’m a doctor.","translation":"اجازه بده - من یک دکتر هستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841732.mp3"},{"sentence":"You’ll never get through – the snow’s two metres deep.","translation":"شما هرگز از آن عبور نخواهید کرد - عمق برف دو متر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841737.mp3"},{"sentence":"Rescue teams have finally made it through to the survivors.","translation":"تیم های امداد و نجات سرانجام به بازماندگان رسیدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841738.mp3"},{"sentence":"We drove right through the town centre.","translation":"درست از مرکز شهر رانندگی کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591376.mp3"},{"sentence":"Carry on straight through the village.","translation":"مستقیم از طریق روستا ادامه دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591380.mp3"}]'::jsonb,9),
('9187807a-8830-5068-a35b-6262b95cf78e','4ad11425-aa7d-58ab-aad4-848c0ef11d4e',4,'see through something','از طریق چیزی دیدن کنید','spoken & written','if you see something through glass, a window etc, you are on one side of the glass etc and it is on the other',null,null,'اگر چیزی را از شیشه، پنجره و غیره ببینید، در یک طرف شیشه و غیره هستید و آن طرف دیگر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I could see her through the window.","translation":"از پنجره می توانستم او را ببینم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000567893.mp3"},{"sentence":"I could see right through the thin curtains.","translation":"درست از میان پرده های نازک می توانستم ببینم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591385.mp3"}]'::jsonb,2),
