('62ac4360-3ec7-51e7-bbc2-bd1228b70729','4ad11425-aa7d-58ab-aad4-848c0ef11d4e',6,'time','زمان','spoken & written','during and to the end of a period of time',null,null,'در طول و تا پایان یک دوره زمانی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The cold weather continued through the spring.","translation":"هوای سرد تا بهار ادامه داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591394.mp3"},{"sentence":"He slept right through the day.","translation":"او تمام روز را درست می خوابید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841739.mp3"},{"sentence":"The fighting went on all through the night.","translation":"درگیری در تمام طول شب ادامه داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841743.mp3"}]'::jsonb,3),
('464148cb-6218-5720-a289-b2b9999da91a','4ad11425-aa7d-58ab-aad4-848c0ef11d4e',7,'process/experience','فرآیند/تجربه','spoken & written','from the beginning to the end of a process or experience',null,null,'از آغاز تا پایان یک فرآیند یا تجربه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The book guides you through the whole procedure of buying a house.","translation":"این کتاب شما را در تمام مراحل خرید خانه راهنمایی می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001591410.mp3"},{"sentence":"When you have been through a terrible experience like that, it takes a long time to recover.","translation":"وقتی تجربه وحشتناکی از این دست را پشت سر گذاشته اید، زمان زیادی طول می کشد تا بهبود پیدا کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000567914.mp3"},{"sentence":"It’s a miracle that these buildings came through the war undamaged.","translation":"این یک معجزه است که این ساختمان ها از طریق جنگ بدون آسیب وارد شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841747.mp3"}]'::jsonb,3),
