('6d2d0278-4258-5cb4-a380-425bc2da0984','438b52cf-0640-5a8f-9a4a-a482224feee0',1,null,null,'spoken & written','the night of this day',null,null,'شب این روز','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m really looking forward to tonight.","translation":"من واقعاً منتظر امشب هستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001611358.mp3"},{"sentence":"Tonight should be fun.","translation":"امشب باید سرگرم کننده باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000577648.mp3"},{"sentence":"Here is tonight’s news bulletin.","translation":"این هم بولتن خبری امشب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000577649.mp3"}]'::jsonb,3),
('9f138174-93a5-5965-9b84-a0aa82aed75c','bf898ee3-063e-5203-bb31-82a5caaec2a2',1,null,null,'spoken & written','completely',null,null,'کاملاً، تماماً؛ به‌کلی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"That’s a totally different matter.","translation":"این یک موضوع کاملاً متفاوت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000580044.mp3"},{"sentence":"It’s like learning a totally new language.","translation":"مانند یادگیری یک زبان کاملاً جدید است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000580045.mp3"},{"sentence":"Terrorism is totally unacceptable in a civilised world.","translation":"تروریسم در دنیای متمدن کاملاً غیرقابل قبول است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001729922.mp3"},{"sentence":"I totally agree.","translation":"کاملا موافقم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001729923.mp3"}]'::jsonb,4),
('00ab5f08-a72f-56f3-859e-92638c3aa93b','bf03155f-00d5-5dd1-9793-126fab0929c7',1,null,null,'spoken & written','someone who is visiting a place for pleasure on holiday',null,null,'گردشگر، توریست؛ گردشگر (جاذبه)؛ گردشگر (فرد)','{}'::text[],'{}'::text[],array['foreign tourists Millions of foreign tourists visit the capital every year.','an American/Japanese etc tourist She saw a crowd of Japanese tourists, cameras at the ready, wandering down the path.','tourists visit a place About six million tourists visit the country each year.','tourists flock to a place (= visit it in large numbers ) Tourists have flocked to the area ever since the TV series was filmed there.','attract/draw tourists They hope to change the image of the city and attract more tourists.','a tourist attraction (= an interesting place for tourists to see or an enjoyable activity for them to do ) Yellowstone National Park is a major tourist attraction.','a tourist destination/centre/spot Egypt became a popular tourist destination in the nineteenth century.','the tourist industry The tourist industry is booming, with more visitors this year than ever before.','the tourist season (= the period in a year when large numbers of tourists visit a place ) Even in the tourist season the beaches don’t get packed.','a group/party of tourists The guide was talking to a party of tourists.']::text[],'[{"sentence":"Cambridge is always full of tourists in the summer.","translation":"کمبریج همیشه در تابستان مملو از گردشگران است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000580982.mp3"},{"sentence":"The Statue of Liberty is a major tourist attraction .","translation":"مجسمه آزادی یکی از جاذبه های گردشگری مهم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001730140.mp3"},{"sentence":"What effect will this have on the local tourist industry ?","translation":"این چه تأثیری بر صنعت گردشگری محلی خواهد داشت؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001730144.mp3"},{"sentence":"Durham, with its cathedral and castle, is a popular tourist centre.","translation":"دورهام، با کلیسای جامع و قلعه، یک مرکز توریستی محبوب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001730150.mp3"}]'::jsonb,4),
('b10d0f7f-ddac-59c1-939f-85b0510906c2','bf03155f-00d5-5dd1-9793-126fab0929c7',2,null,null,'spoken & written',null,null,'medical/sex/libel etc tourist','گردشگر، توریست؛ گردشگر (جاذبه)؛ گردشگر (فرد)','{}'::text[],'{}'::text[],array['foreign tourists Millions of foreign tourists visit the capital every year.','an American/Japanese etc tourist She saw a crowd of Japanese tourists, cameras at the ready, wandering down the path.','tourists visit a place About six million tourists visit the country each year.','tourists flock to a place (= visit it in large numbers ) Tourists have flocked to the area ever since the TV series was filmed there.','attract/draw tourists They hope to change the image of the city and attract more tourists.','a tourist attraction (= an interesting place for tourists to see or an enjoyable activity for them to do ) Yellowstone National Park is a major tourist attraction.','a tourist destination/centre/spot Egypt became a popular tourist destination in the nineteenth century.','the tourist industry The tourist industry is booming, with more visitors this year than ever before.','the tourist season (= the period in a year when large numbers of tourists visit a place ) Even in the tourist season the beaches don’t get packed.','a group/party of tourists The guide was talking to a party of tourists.']::text[],'[]'::jsonb,0),
('209af455-fe28-53b1-8a5d-0fe8a2b4b80c','b92fbefe-e197-5a7f-8629-a41b739702c3',1,'direction','جهت','spoken & written','used to say that someone or something moves, looks, faces etc in the direction of someone or something',null,null,'به سمتِ، رو به؛ رو به (حالت)؛ نزدیک (به)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He noticed two policemen coming towards him.","translation":"او متوجه شد دو پلیس به سمت او می آیند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000581219.mp3"},{"sentence":"All the windows face toward the river.","translation":"تمام پنجره ها رو به رودخانه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000581220.mp3"},{"sentence":"He was standing with his back towards me.","translation":"پشت به من ایستاده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000581221.mp3"}]'::jsonb,3),
('047d2576-f6bd-52f6-b368-3e2de8218ea1','b92fbefe-e197-5a7f-8629-a41b739702c3',2,'producing a result','تولید نتیجه','spoken & written','in a process that will produce a particular result',null,null,'در فرآیندی که نتیجه خاصی به همراه خواهد داشت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"These negotiations are the first step toward reaching an agreement.","translation":"این مذاکرات اولین گام برای دستیابی به توافق است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000581227.mp3"},{"sentence":"The crisis continued as Britain drifted towards war.","translation":"این بحران زمانی ادامه یافت که بریتانیا به سمت جنگ پیش رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000581228.mp3"}]'::jsonb,2),
