('4ba79dc8-3724-509b-843b-dfd24475bde3','96fdbed0-25fa-5358-a107-fde37c17945d',1,'problems','مشکلات','spoken & written','problems or difficulties','[ uncountable ]',null,'درسر، مشکل؛ دردسر (فرد)؛ درسر (حالت)','{}'::text[],'{}'::text[],array['have trouble He is having trouble getting his message across to the voters.','have no trouble We had no trouble finding her house.','cause trouble I hope the delay hasn’t caused you any trouble.','there is trouble There was some trouble at her office, but she didn’t say what it was.','mean/spell trouble (= mean there will be trouble ) They are now much more competitive, which can only spell trouble for their rivals.','be asking for trouble (= be silly or dangerous ) It’s asking for trouble to wear high-heeled shoes on a long walk.','avoid trouble We avoid trouble by planning carefully.','big/great trouble High interest rates spell big trouble for homeowners.','terrible trouble I’ve been having terrible trouble sleeping.','endless trouble (= a lot of trouble ) They had endless trouble with the water supply.','serious trouble I was having serious trouble knowing where to begin.','teething troubles British English (= small problems that you have when you first start doing a new job or using a new system ) There were a lot of teething troubles in the first year.','what the trouble is A couple of nurses rushed into the room to see what the trouble was.','without any/much trouble (= easily ) The work was carried out without any trouble.']::text[],'[{"sentence":"We’re having a lot of trouble with the new computer system.","translation":"ما با سیستم کامپیوتری جدید مشکل زیادی داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000560931.mp3"},{"sentence":"Recent stock market losses point to trouble ahead.","translation":"زیان های اخیر بازار سهام نشان دهنده مشکلات پیش رو است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001845895.mp3"}]'::jsonb,2),
('316ce0b9-a949-52db-8961-a6620ef21f67','96fdbed0-25fa-5358-a107-fde37c17945d',2,'bad point','نقطه بد','spoken & written','used when saying what is bad about a person or situation or what causes problems','[ singular ]',null,'هنگام گفتن اینکه چه چیزی در مورد یک فرد یا موقعیت بد است یا چه چیزی باعث ایجاد مشکل می شود استفاده می شود','{}'::text[],'{}'::text[],array['have trouble He is having trouble getting his message across to the voters.','have no trouble We had no trouble finding her house.','cause trouble I hope the delay hasn’t caused you any trouble.','there is trouble There was some trouble at her office, but she didn’t say what it was.','mean/spell trouble (= mean there will be trouble ) They are now much more competitive, which can only spell trouble for their rivals.','be asking for trouble (= be silly or dangerous ) It’s asking for trouble to wear high-heeled shoes on a long walk.','avoid trouble We avoid trouble by planning carefully.','big/great trouble High interest rates spell big trouble for homeowners.','terrible trouble I’ve been having terrible trouble sleeping.','endless trouble (= a lot of trouble ) They had endless trouble with the water supply.','serious trouble I was having serious trouble knowing where to begin.','teething troubles British English (= small problems that you have when you first start doing a new job or using a new system ) There were a lot of teething troubles in the first year.','what the trouble is A couple of nurses rushed into the room to see what the trouble was.','without any/much trouble (= easily ) The work was carried out without any trouble.']::text[],'[{"sentence":"The trouble with you is that you don’t listen.","translation":"مشکل شما این است که گوش نمی دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000560958.mp3"},{"sentence":"The trouble is there are too many people and not enough places.","translation":"مشکل اینجاست که تعداد افراد زیاد است و مکان کافی نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000560959.mp3"},{"sentence":"But no one ever remembers – that’s the trouble .","translation":"اما هیچ کس هرگز به یاد نمی آورد - مشکل این است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600451.mp3"},{"sentence":"You never think, that’s your trouble .","translation":"شما هرگز فکر نمی کنید، این مشکل شماست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600455.mp3"}]'::jsonb,4),
